  /* ===================================================================
     1. CONFIG
     =================================================================== */
  var CONFIG = {
    title:   "Blight",
    /* One sentence, and nothing else: the demo caption is dropped in the SKIN
       because the stage below already plays the drag / release / match beat. */
    tagline: "<b class=\"w-aim\">Aim</b>, <b class=\"w-fire\">shoot</b> and match 3 bubbles to push the black magic back",
    /* NO CLOCK. The blight is the clock: it winds up until the whole wall has
       turned, and the round ends there. A player either has what they came
       for before that — the three stars of a level, a score on a playable —
       or the rot takes the board. See THE ROT RACE in section 6. */
    gameSeconds: 0,
    storeUrl: {
      ios:     "https://newrare.app/#playables",
      android: "https://newrare.app/#playables",
      fallback:"https://newrare.app/#playables"
    },
    designWidth: 720, designHeight: 1280, bg: "#0a0e24",
    // The grid hangs from Layout.top and the launcher sits above the CTA bar,
    // so nothing important ever ends up under the HUD or a notch.
    layout: { hudHeight: 150, ctaHeight: 118, sideMargin: 0 },
    intro: { logo: null, demo: "aim", caption: "" },
    hud: { score: true, timer: false },
    /* THE BED. One track, six windows of it. Five are the round's, named on the
       bands below — and the sixth is the quiet, slower one the menus sit on.
       The entry points are the track's own seams, measured and not guessed
       (see docs/MUSIC.md): the body drops at 12 s and breaks again at 48, 78,
       102 and 132, and the outro starts at 156. A playable has no level and no
       menu, so it ships the first window alone,
       a seam of pre-roll in front of it (CONFIG.music.cut). */
    /* `seam`: every window loops on the bar, two beats of crossfade ending on
       its downbeat (docs/MUSIC.md, The seam); `cut`: the playable's window,
       one seam of pre-roll into its embedded cut. */
    music: {
      volume: 0.10, fade: 2.0, seam: 1.5,
      cut: { from: 1.5, length: 39 },
      menu: { from: 0, length: 33.128, rate: 0.85, gain: 0.5 }
    },

    /* --- THE FIVE BANDS OF THE CLIMB -------------------------------------
       Six levels apiece, and the band is the one stretch of the game the
       player is already told about: the level map names them on its own card
       (Warm-up, Pressure, Squeeze, Overdrive, Meltdown). So both things that
       can turn over without touching the mechanic do it there, together — the
       PICTURE the round and the end screen are played over, and the STRETCH of
       the track under them.

       The five scenes are one descent into the blight, painted in that order:
       the marsh it started in, the ruins it has eaten, the gorge, the castle,
       and the throne room at the heart of it. `scene` is a key of CONFIG.art,
       injected by the builder out of assets/image/embed/blight-background-phone-NN.webp
       (see docs/ENGINE.md, CONFIG.art) — the game names no file.

       A playable is one round at level 0: it rides the first band, and it is
       the only scene and the only window the builder embeds in it. */
    bands: [
      // levels   the scene                        the stretch of the track
      { scene: "backgroundPhone01", music: { from: 12,  length: 39 } },  //  1-6   Warm-up
      { scene: "backgroundPhone02", music: { from: 48,  length: 30 } },  //  7-12  Pressure
      { scene: "backgroundPhone03", music: { from: 78,  length: 24 } },  // 13-18  Squeeze
      { scene: "backgroundPhone04", music: { from: 102, length: 27 } },  // 19-24  Overdrive
      { scene: "backgroundPhone05", music: { from: 132, length: 21 } }   // 25-30  Meltdown
    ],
    copy: {
      start:"Tap to play", ctaBar:"Install now", ctaEnd:"Play the full game",
      replay:"Replay the demo", scoreLabel:"Score", timeLabel:"Time",
      endScore:"Final score", gameOver:"Contaminated!", timeUp:"Time's up!",
      rotten:"The rot wins!", rotLabel:"Rot"
    },

    /* --- game tunables --- */
    bubbleR: 30,                   // radius (diameter 60 => 12 columns fit 720)
    cols: 12,                      // bubbles on a non-offset row (offset rows hold cols-1)
    startRows: 6,                  // rows present at the start
    launcherOffset: 60,            // launcher this far above Layout.bottom
    dangerOffset: 150,             // a bubble reaching this line loses the round
    maxAimDeg: 82,                 // clamp the aim so you cannot shoot sideways
    shootSpeed: 1150,              // px/sec
    addRowShots: 5,                // push a fresh row down every N shots (pressure)
    blightInterval: 3.2,           // seconds between spreads, at the START of a round
    blightRush: 0.22,              // ...and this fraction of it once the ramp is done
    blightRamp: 55,                // seconds the wind-up takes
    blightBurst: 3,                // bubbles one late tick takes, against one early
    rotGrace: 12,                  // a board dealt with no rot gets this long clean
    blightFill: 1.5,               // seconds for the cloud to fill a fresh bubble
    wallSuperChance: 0.06,         // chance a wall bubble is a rainbow SUPER
    shotSuperChance: 0.12,         // chance the launcher hands you a SUPER
    gridOffset: 38,                // the wall hangs this far under Layout.top, so the
                                   // web target's level pill never covers the first row
    // The cure is as big as the disease: both of these are read against how
    // much of the wall has turned (see cureTargets).
    cureReach: 2,                  // hex steps the cure travels on a clean board
    cureReachMax: 4,               // ...and on one the rot has taken over
    cureMin: 2,                    // bubbles one rainbow saves on a clean board
    cureMax: 14,                   // ...and on one the rot has taken over
    cureScore: 40,                 // what one purified bubble is worth
    fallBonus: 15,                 // a cut-off bubble bursting on the floor

    // Only THREE base colours — easy matching, punchy reads.
    palette: [
      { light:"#ffd3dc", core:"#ff4d6d", edge:"#c11e46", glow:"rgba(255,77,109,.95)" },
      { light:"#fff1bd", core:"#ffc93c", edge:"#dc8a00", glow:"rgba(255,201,60,.95)" },
      { light:"#cfe6ff", core:"#3aa0ff", edge:"#1663d6", glow:"rgba(58,160,255,.95)" }
    ]
  };

  /* ===================================================================
     2. ASSETS
     =================================================================== */
  var ASSETS = {
    /* EMPTY, and on purpose. Two pictures used to be here and both of them are
       the painted artwork's job now:

         `logo` — this game ships a painted logotype
                  (assets/image/master/blight-title.png) and the shell hides
                  #app-icon as soon as one exists, so an embedded app icon is
                  84 KB of base64 in every build that nothing ever draws. The
                  site card reads the icon out of assets/image/icon/thumb/.
         `bg`   — the round's backdrop WAS this game's scene re-encoded as a
                  181 KB jpeg, i.e. a second copy of
                  blight-background-phone-01. It comes from CONFIG.art now
                  (`ArtImages`, see buildBackground): the same picture at a
                  third of the bytes, and four more of them — one per band of
                  the climb. */
    images: {},
    sounds: {
      // The background bed, looped and crossfaded by Music (see CONFIG.music
      // and CONFIG.bands, which name the window each band of the climb rides).
      // The playable's cut is the FIRST band's window and nothing else — three
      // minutes of track is material an ad downloads and can never reach. The
      // web target ships the whole of it instead (`web.music` in the manifest):
      //   ffmpeg -ss 10.5 -t 40.5 -i assets/audio/music/blight.mp3 \
      //          -ac 1 -ar 44100 -b:a 64k music.mp3
      music: "data:audio/mpeg;base64,",
      // No sfx clip here: every key the game plays is a role of the house kit,
      // mapped by `sfx` in manifest.json and injected by the builder.
    }
  };

  /* ===================================================================
     6. GAME — BLIGHT
     A classic hexagonal bubble shooter, tuned for a smooth frame rate:

       - A hex grid hangs from the top of Layout. Rows are staggered; a
         `rowShift` counter lets new rows be pushed in from the top while every
         existing bubble keeps its geometry (parity = (row + rowShift)).
         Only THREE base colours are used, so matching is instant to read.
       - SUPER bubbles: rare rainbow JOKERS, and they read two ways. One
         sitting in the wall takes the colour of the bubble that lands against
         it, so it welds two clusters into one match. One fired from the
         launcher is thrown at the rot: on impact it PURIFIES the blighted
         bubbles around it, handing each of them a colour back — which is
         very often a match of its own.
       - THE CHAIN: a cluster never vanishes in one frame. Its bubbles go off
         one after the other, ~45 ms apart, each scoring on its own, so a big
         clear reads as a chain reaction instead of a hole appearing.
       - BLIGHT: one dark bubble spreads to a neighbour, and it never matches
         by colour — the only way out is to cut it off from the ceiling so it
         falls, or to throw a rainbow at it.
       - THE ROT RACE: there is no clock on this round. The spread winds up
         instead — the gap between two ticks closes, then a tick starts taking
         several bubbles at once — and the round ends when the whole wall has
         turned. That is the shape of the game: the player is racing the rot
         for their three stars, not racing a countdown.
       - Drag to aim (dotted trajectory with one wall bounce), release to fire.
       - SOAP: the bubbles are thin films, not marbles. Every one of them is a
         damped spring (see THE SOAP LAYER below) — the shot stretches along
         its flight, squashes on impact, and the cluster it hits absorbs the
         blow as a wave that travels outward through the foam.
       - THE OPENING BOARD: a level is not only tuned, it is DEALT. The thirty
         levels of the web target each open on a board of their own — a
         colour motif on a full wall, or a silhouette hung from the ceiling
         (a heart, a diamond, a ring, a cross...). See THE OPENINGS below.
       - PERFORMANCE: every bubble and the background are pre-rendered once to
         a cached sprite and blitted with drawImage — no per-frame gradients or
         shadowBlur. The deformation is an affine squash on that blit, so the
         whole board can breathe for the cost of one transform per bubble. All
         the juice goes through the engine's Fx layer.
     =================================================================== */
  var Game = (function () {
    /* The band of the climb in force, out of CONFIG.bands — the scene the
       round and the end screen are painted over and the stretch of the track
       under them. reset() is what moves it. */
    var BAND = null;
    var R = CONFIG.bubbleR, COLS = CONFIG.cols, PAL = CONFIG.palette;
    var ROWH = R * Math.sqrt(3);            // vertical spacing between hex rows
    var SPEED = CONFIG.shootSpeed;
    var MAX_AIM = CONFIG.maxAimDeg * Math.PI / 180;
    /* Read at every reset, not once at load: the web target's level layer
       lerps these three in CONFIG before a round starts (docs/LEVELS.md), and
       a value copied when the file parsed would never see the change. A
       playable reads them once and they never move. */
    var ADD_SHOTS, WALL_SUP, SHOT_SUP;
    /* How many of the palette this round is allowed to deal. The opening of a
       level caps it (the first three are played on two colours); every random
       colour on the board — the wall, the pushed rows, the launcher — goes
       through it, so the cap holds for the whole round and not just the seed. */
    var COLORN = PAL.length;
    function readTunables() {
      ADD_SHOTS = CONFIG.addRowShots;
      WALL_SUP = CONFIG.wallSuperChance;
      SHOT_SUP = CONFIG.shotSuperChance;
      var open = levelOpening();
      COLORN = Math.max(2, Math.min(open ? open.colors : PAL.length, PAL.length));
    }
    var PI2 = Math.PI * 2;
    var COLLIDE = R * 2 * 0.9;              // centres this close => touching

    /* --- THE SOAP LAYER ---------------------------------------------------
       Every bubble carries a damped spring: an amplitude, a phase, the axis it
       is being squeezed along, and a delay before it starts. The delay is what
       turns a single impact into a WAVE — a ripple hands each bubble a start
       time proportional to its distance from the impact, so the foam absorbs
       the shot ring by ring instead of all at once.

       `def` (= amplitude * cos(phase)) is positive when the film is compressed
       along its axis: the blit is squashed by SQ across that axis and stretched
       by ST along the other one, so the bubble is genuinely not round while it
       settles. A negative `def` is the rebound — and it is also how the flying
       ball is stretched along its own flight. */
    var OSC_W = 17.5;                       // spring frequency (rad/s)
    var OSC_K = 4.4;                        // damping — ~0.8 s to settle
    var SQ = 0.30, ST = 0.26;               // how far a unit of `def` deforms
    var WAVE_SPEED = 900;                   // px/s the impact travels through the foam
    // The chain: how long one bubble waits for the one before it.
    var POP_STEP = 0.045, CURE_STEP = 0.075;
    var BREATHE = 0.017;                    // idle life: nothing on this board is ever still

    // --- geometry, derived from Layout so the grid never hides under the HUD
    // or the CTA bar and never sits behind a notch ---------------------------
    var GRID_TOP = 0, LX = 0, LY = 0, DANGER_Y = 0, FLOOR_Y = 0, ROWS = 22;
    // The launcher row: the loaded bubble, the swap ring, the next bubble.
    var NEXT_X = 0, SWAP_X = 0;
    // The swap ring's own tap radius stops short of the loaded bubble: a drag
    // that starts on the bubble is an aim, not a trade.
    var SWAP_R = 25, SWAP_HIT = 34, NEXT_HIT = 40;

    // --- state -------------------------------------------------------------
    var grid;            // grid[r][c] = colour index or null
    var sup;             // sup[r][c]  = true if that bubble is a SUPER
    var blk;             // blk[r][c]  = true if that bubble is contaminated
    var inf;             // inf[r][c]  = 0..1, how far the cloud has filled it
    var infAng;          // infAng[r][c] = where the film was pierced (world angle)
    var wobA, wobP, wobAng, wobD;   // the spring: amplitude, phase, axis, pending delay
    var rowShift;        // parity offset so pushed-in rows stay consistent
    var score, ball, nextColor, nextSuper;
    var aimAngle, aiming, aimLoad;
    var shotCount, maxCombo, streak, ended, blackTimer, totalCleared;
    var fallers, splashes, trail, bgT, fieldY, launchPunch, idleTimer;
    var roundT;          // seconds since the round started — the rot's ramp
    var rotPct, rotCount, liveCount;   // how much of the wall has turned
    var chain;           // the running chain of pops / cures, walked by update()
    var swapSpin;        // the swap ring, spinning down after a trade

    // --- cached sprites (built once — the core perf win) -------------------
    var bubbleSprites = null, superSprite = null, blackSprite = null, puffSprite = null, bgCanvas = null;
    /* What each cache was built FOR. A replay used to throw the full-frame
       background away and paint an identical one (3.5 MB of pixels per round,
       reclaimed by a major GC mid-round a few rounds later — the hitch that
       never happens in the first round). Each cache now rebuilds only when an
       input it is drawn from changes, and frees the canvas it replaces. */
    var sprSig = "", bgSig = "";

    function geometry() {
      // The wall starts a little under the top band: the level pill of the web
      // target hangs there, and a bubble behind it is a bubble the player
      // cannot read (docs/LEVELS.md — the pill is the shell's, not the HUD's).
      GRID_TOP = Layout.top + (CONFIG.gridOffset || 0);
      LX = view.w / 2;
      LY = Layout.bottom - CONFIG.launcherOffset;
      DANGER_Y = Layout.bottom - CONFIG.dangerOffset;
      FLOOR_Y = Layout.bottom - 4;             // where a cut-off bubble bursts
      NEXT_X = LX + 118;
      SWAP_X = (LX + R + NEXT_X - R * 0.6) / 2;
    }
    // A resize changes view.dpr, and the film's rim is a one-pixel affair: the
    // sprites are re-rendered at the new device resolution rather than scaled.
    // On the web build this runs BEFORE the first reset(): both builders read
    // only what is in force here, and their signatures decide whether to redo.
    function onResize() {
      geometry();
      buildSprites();
      buildBackground();
    }

    // --- hex geometry ------------------------------------------------------
    function isOffset(r) { return (((r + rowShift) % 2) + 2) % 2 === 1; }
    function rowCols(r)  { return isOffset(r) ? COLS - 1 : COLS; }
    function cellX(r, c) { return R + c * 2 * R + (isOffset(r) ? R : 0); }
    function cellY(r)    { return GRID_TOP + r * ROWH + R; }
    function validCell(r, c) { return r >= 0 && r < ROWS && c >= 0 && c < rowCols(r); }
    function key(r, c) { return r + "_" + c; }

    function neighbors(r, c) {
      if (isOffset(r)) return [[r, c - 1], [r, c + 1], [r - 1, c], [r - 1, c + 1], [r + 1, c], [r + 1, c + 1]];
      return [[r, c - 1], [r, c + 1], [r - 1, c - 1], [r - 1, c], [r + 1, c - 1], [r + 1, c]];
    }

    function makeGrid(fill) {
      var g = [];
      for (var r = 0; r < ROWS; r++) {
        var row = [];
        for (var c = 0; c < COLS; c++) row.push(fill);
        g.push(row);
      }
      return g;
    }


    /* --- THE OPENINGS -----------------------------------------------------
       Thirty levels, thirty boards. A level that only moved a few numbers
       looks like the one before it, so what changes here is the wall the
       player finds on screen when the round starts: the first three teach
       the mechanic on two colours, and from there every level opens on a
       motif it does not share with any other.

       An opening is either a FULL wall of `rows` rows painted by a colour
       pattern, or an `art` SILHOUETTE — a shape hung from the ceiling, its
       colours dealt by the same patterns. Nothing else about the game
       changes: the knobs stay the manifest's lerp (docs/LEVELS.md), the
       pushed rows stay random, and a playable — which has no level — still
       opens on CONFIG.startRows of pure random.

       A shape is a FIGURE, written in the unit square of the wall: `u` runs
       -1 to +1 across a row and `v` runs 0 on the ceiling row to 1 on the last
       row of the shape. A shape whose point is the GRID itself — one bubble
       out of two, a lace of holes — is written as `cell(r, c)` instead, in
       cell indices, because a lattice rounded off a continuous figure comes
       out with stutters in it. Rows are staggered by half
       a bubble, so a shape written column by column would come out lopsided and,
       worse, cut in two — the right arm of a ring would hang off nothing. In
       `u` it is simply symmetric. Whatever a shape still leaves unattached is
       pruned rather than dropped, so nothing rains down before the first shot. */
    var LV_ART = {
      // three vertical bars, each one hanging from the ceiling on its own
      bars:     { rows: 6, hit: function (u, v) {
        return Math.min(Math.abs(u + 0.62), Math.abs(u), Math.abs(u - 0.62)) < 0.19; } },
      // losange
      diamond:  { rows: 9, hit: function (u, v) {
        return Math.abs(u) + Math.abs(2 * v - 1) < 1.15; } },
      // cercle: an open ring, the hole in the middle is the point
      ring:     { rows: 9, hit: function (u, v) {
        return Math.abs(Math.sqrt(u * u + (2 * v - 1) * (2 * v - 1)) - 0.75) < 0.32; } },
      // coeur: the implicit curve (x^2+y^2-1)^3 = x^2 y^3, notch included
      heart:    { rows: 9, hit: function (u, v) {
        var x = u * 1.25, y = 1.15 - v * 2.00, a = x * x + y * y - 1;
        return a * a * a - x * x * y * y * y < 0; } },
      cross:    { rows: 8, hit: function (u, v) {
        return Math.abs(u) < 0.28 || Math.abs(2 * v - 1) < 0.28; } },
      xcross:   { rows: 9, hit: function (u, v) {
        return Math.abs(Math.abs(u) - Math.abs(2 * v - 1)) < 0.30; } },
      chevron:  { rows: 6, hit: function (u, v) {
        return Math.abs(Math.abs(u) - v * 1.05) < 0.22; } },
      funnel:   { rows: 6, hit: function (u, v) {
        return Math.abs(u) < 1.10 - v * 0.98; } },
      arrow:    { rows: 8, hit: function (u, v) {
        return v < 0.45 ? Math.abs(u) < 0.15 + v * 1.8 : Math.abs(u) < 0.22; } },
      /* the letter S, written as five bars: the three horizontals and the two
         verticals that join them on opposite sides. */
      sletter:  { rows: 10, hit: function (u, v) {
        var w = 0.72;
        if (v < 0.21) return Math.abs(u) < w;                   // the top bar
        if (v < 0.41) return u > -w && u < -w + 0.36;           // down the left
        if (v < 0.62) return Math.abs(u) < w;                   // the middle bar
        if (v < 0.82) return u < w && u > w - 0.36;             // down the right
        return Math.abs(u) < w; } },                            // the bottom bar
      // one bubble out of two: nothing touches its neighbour in the same row,
      // so every match has to be read on the diagonals
      lattice:  { rows: 7, cell: function (r, c) { return (r + c) % 2 === 1; } },
      // layers of triangles, hanging point-down off a solid ceiling
      triangles:{ rows: 7, hit: function (u, v) {
        var t = (u + 1) * 1.5, f = t - Math.floor(t);
        return Math.abs(f - 0.5) < 0.5 * (1 - v * 0.86); } },
      // an arrow pointing DOWN: the shaft hangs from the ceiling, the head
      // opens under it (`arrow` above is the same figure the other way up)
      arrowDown:{ rows: 8, hit: function (u, v) {
        return v < 0.44 ? Math.abs(u) < 0.20
                        : Math.abs(u) < 1.12 - (v - 0.44) * 1.85; } },
      /* a cherry: two stems fanning out of the ceiling and a berry on each.
         The berries are ellipses, not circles — a row is taller than a column
         is wide, so a circle in (u,v) would come out standing up. */
      cherry:   { rows: 10, hit: function (u, v) {
        if (v < 0.56 && Math.abs(Math.abs(u) - v * 0.92) < 0.11) return true;
        var bx = 0.50, by = 0.74, rx = 0.40, ry = 0.26;
        var dl = (u + bx) / rx, dr = (u - bx) / rx, dy = (v - by) / ry;
        return dl * dl + dy * dy < 1 || dr * dr + dy * dy < 1; } },
      // a bow tie: two triangles nose to nose, hung on the two full columns
      // the figure leaves at either edge
      bowtie:   { rows: 9, hit: function (u, v) {
        return Math.abs(2 * v - 1) < 0.16 + Math.abs(u) * 0.92; } },
      /* a mushroom: the cap fills the ceiling row and the stem hangs under
         it. A star was the other candidate here and it does not survive this
         grid — five points over twelve columns is a blob, and an astroid's
         points are thinner than the gap between two columns. */
      mushroom: { rows: 9, hit: function (u, v) {
        if (v < 0.50) return Math.abs(u) < 0.98 * Math.sqrt(Math.max(0, 1 - (v / 0.52) * (v / 0.52)));
        return Math.abs(u) < 0.27; } },
      // a full wall with one bubble in three punched out, on a diagonal
      lace:     { rows: 8, cell: function (r, c) { return (c + r * 2) % 3 !== 0; } },
      // leaning bands. The lean is well under one period, so every band still
      // crosses the ceiling — a band that did not would be pruned whole, which
      // is what a wandering zigzag came out as: fragments.
      slant:    { rows: 7, hit: function (u, v) {
        var t = (u + v * 0.35) * 1.1; t -= Math.floor(t);
        return Math.abs(t - 0.5) < 0.28; } },
      hourglass:{ rows: 11, hit: function (u, v) {
        return Math.abs(u) < 0.18 + Math.abs(2 * v - 1) * 0.92; } },
      pillars:  { rows: 6, hit: function (u, v) {
        return Math.abs(u) > 0.55 || Math.abs(v * 2.5 - Math.round(v * 2.5)) < 0.20; } },
      // a face: a disc with two eyes punched out and a mouth cut across it
      face:     { rows: 9, hit: function (u, v) {
        var y = 2 * v - 1;
        if (Math.sqrt(u * u + y * y * 0.85) > 1.0) return false;
        var ex = Math.abs(u) - 0.42, ey = y + 0.35;
        if (Math.sqrt(ex * ex + ey * ey) < 0.22) return false;
        return !(Math.abs(y - 0.45) < 0.16 && Math.abs(u) < 0.45); } }
    };

    /* `rows` is read only when there is no `art` — a mask brings its own
       height. `seeds` is how many blighted bubbles the board opens with: the
       first two levels open on none at all, which is what makes the third
       one land. The blight still spreads one bubble per tick whatever the
       count, so more seeds means more fronts, not a faster rot. */
    var LV_OPEN = [
      { rows: 2, colors: 2, seeds: 0, fill: "clusters" },   //  1  grappes de couleur
      { rows: 2, colors: 2, seeds: 0, fill: "alternate" },  //  2  une sur deux
      { rows: 2, colors: 2, seeds: 1, fill: "random" },     //  3  la premiere contamination
      { rows: 3, colors: 3, seeds: 1, fill: "clusters" },   //  4  trois couleurs
      { art: "bars",    colors: 3, seeds: 1, fill: "clusters" },
      { art: "sletter", colors: 3, seeds: 1, fill: "clusters" },
      { art: "diamond", colors: 3, seeds: 1, fill: "clusters" },
      { art: "lattice", colors: 3, seeds: 1, fill: "alternate" },
      { art: "ring",    colors: 3, seeds: 1, fill: "random" },
      { art: "heart",   colors: 3, seeds: 1, fill: "clusters" },
      { rows: 5, colors: 3, seeds: 1, fill: "stripesV" },
      { art: "cross",   colors: 3, seeds: 1, fill: "random" },
      { art: "slant",   colors: 3, seeds: 2, fill: "clusters" },
      { art: "triangles", colors: 3, seeds: 2, fill: "stripesH" },
      { art: "funnel",  colors: 3, seeds: 1, fill: "random" },
      { art: "xcross",  colors: 3, seeds: 2, fill: "clusters" },
      { rows: 6, colors: 3, seeds: 2, fill: "bands" },
      { art: "chevron", colors: 3, seeds: 2, fill: "random" },
      { art: "arrowDown", colors: 3, seeds: 2, fill: "random" },
      { art: "cherry",  colors: 3, seeds: 2, fill: "clusters" },
      { rows: 6, colors: 3, seeds: 2, fill: "diagWide" },
      { art: "face",    colors: 3, seeds: 2, fill: "clusters" },
      { art: "bowtie",  colors: 3, seeds: 2, fill: "checker" },
      { art: "arrow",   colors: 3, seeds: 3, fill: "random" },
      { art: "mushroom", colors: 3, seeds: 2, fill: "clusters" },
      { rows: 7, colors: 3, seeds: 3, fill: "stripesH" },
      { art: "pillars", colors: 3, seeds: 3, fill: "random" },
      { art: "hourglass", colors: 3, seeds: 3, fill: "clusters" },
      { art: "lace",    colors: 3, seeds: 3, fill: "diagWide" },
      { rows: 9, colors: 3, seeds: 3, fill: "random" }      // 30  le mur entier
    ];

    // null for a playable, for the endless run and for anything off the map:
    // all three keep the original random wall of CONFIG.startRows.
    function levelOpening() {
      var n = CONFIG.level | 0;
      return (n >= 1 && n <= LV_OPEN.length) ? LV_OPEN[n - 1] : null;
    }
    readTunables();

    /* The colour patterns. `k` is COLORN, so every one of them reads on two
       colours as well as on three. `clusters` is the only one with memory:
       a 3x2 block of cells shares one colour, which is what makes a first
       level clear in long cascades instead of one match at a time. */
    var clusterMap = {};
    function patternColor(name, r, c, k) {
      switch (name) {
        case "alternate": return (r + c) % k;                               // one out of two
        case "stripesH":  return r % k;                                     // one colour per row
        case "stripesV":  return (c >> 1) % k;                              // two-wide vertical bands
        case "bands":     return (c >> 2) % k;                              // four-wide vertical bands
        case "checker":   return ((r >> 1) + (c >> 1)) % k;                 // 2x2 blocks
        case "diagonal":  return (r + (c >> 1)) % k;                        // wide diagonals
        case "diagWide":  return Math.floor((r + (c >> 1)) / 2) % k;        // ...twice as wide
        case "clusters":
          var g = (r >> 1) * 8 + Math.floor(c / 3);
          if (clusterMap[g] == null) clusterMap[g] = Rand.int(0, k - 1);
          return clusterMap[g];
      }
      return Rand.int(0, k - 1);
    }

    /* A silhouette has to hang from the ceiling. Anything a mask leaves
       unattached is removed here and not handed to dropFloating: a faller
       the player never shot at would rain down before the first tap. */
    function pruneFloating() {
      var ok = {}, q = [], r, c, i;
      for (c = 0; c < rowCols(0); c++)
        if (grid[0][c] !== null) { ok[key(0, c)] = true; q.push([0, c]); }
      while (q.length) {
        var cur = q.pop(), nb = neighbors(cur[0], cur[1]);
        for (i = 0; i < nb.length; i++) {
          var nr = nb[i][0], nc = nb[i][1];
          if (!validCell(nr, nc) || grid[nr][nc] === null) continue;
          var k = key(nr, nc);
          if (ok[k]) continue;
          ok[k] = true; q.push([nr, nc]);
        }
      }
      for (r = 0; r < ROWS; r++)
        for (c = 0; c < rowCols(r); c++)
          if (grid[r][c] !== null && !ok[key(r, c)]) { grid[r][c] = null; sup[r][c] = false; }
    }

    // The blight starts in `count` random non-super cells, already full: the
    // player is shown where the rot is before it has moved.
    function seedBlight(count) {
      var cand = [], r, c;
      if (count <= 0) return;
      for (r = 0; r < ROWS; r++)
        for (c = 0; c < rowCols(r); c++)
          if (grid[r][c] !== null && !sup[r][c] && !blk[r][c]) cand.push([r, c]);
      for (var i = 0; i < count && cand.length; i++) {
        var j = Rand.int(0, cand.length - 1), pick = cand[j];
        cand.splice(j, 1);
        blk[pick[0]][pick[1]] = true;
        inf[pick[0]][pick[1]] = 1;
      }
    }

    function fillStartRows() {
      var open = levelOpening();
      var art = open && open.art ? LV_ART[open.art] : null;
      var fill = open ? open.fill : "random";
      var rows = art ? art.rows : (open ? open.rows : CONFIG.startRows);
      var half = view.w / 2, span = half - R;
      rows = Math.min(rows, ROWS - 2);
      clusterMap = {};
      for (var r = 0; r < rows; r++) {
        var n = rowCols(r), v = rows > 1 ? r / (rows - 1) : 0;
        for (var c = 0; c < n; c++) {
          if (art && !(art.cell ? art.cell(r, c) : art.hit((cellX(r, c) - half) / span, v))) continue;
          grid[r][c] = patternColor(fill, r, c, COLORN);
          sup[r][c] = Rand.chance(WALL_SUP);
        }
      }
      if (art) pruneFloating();
      seedBlight(open ? open.seeds : 1);
    }

    function activeColors() {
      var seen = {}, list = [];
      for (var r = 0; r < ROWS; r++) {
        for (var c = 0; c < rowCols(r); c++) {
          var v = grid[r][c];
          if (v !== null && !sup[r][c] && !seen[v]) { seen[v] = true; list.push(v); }
        }
      }
      return list;
    }
    function pickShootColor() {
      var a = activeColors();
      return a.length ? Rand.pick(a) : Rand.int(0, COLORN - 1);
    }

    /* --- the spring, driven ------------------------------------------------
       setWobble arms one bubble; ripple arms the whole board from a point and
       is what every impact on this game goes through. */
    function setWobble(r, c, amp, ang, delay) {
      if (!validCell(r, c) || grid[r][c] === null) return;
      // A bubble already shaking harder than this keeps its own motion.
      if (wobD[r][c] <= 0 && wobA[r][c] > amp) return;
      wobA[r][c] = amp; wobAng[r][c] = ang; wobP[r][c] = 0; wobD[r][c] = delay || 0;
    }
    // One blow, absorbed ring by ring: distance sets both the delay and the
    // amplitude, so what the player sees leaving the impact is a wave.
    function ripple(ox, oy, amp, reach) {
      var reach2 = reach * reach;
      for (var r = 0; r < ROWS; r++) {
        var n = rowCols(r);
        for (var c = 0; c < n; c++) {
          if (grid[r][c] === null) continue;
          var dx = cellX(r, c) - ox, dy = cellY(r) - oy;
          var d2 = dx * dx + dy * dy;
          if (d2 > reach2) continue;
          var d = Math.sqrt(d2), k = 1 - d / reach;
          setWobble(r, c, amp * k * k, Math.atan2(dy, dx), d / WAVE_SPEED);
        }
      }
    }
    // The live deformation of one cell: 0 while its wave has not reached it.
    function deformAt(r, c) {
      var a = wobA[r][c];
      if (a <= 0 || wobD[r][c] > 0) return 0;
      return a * Math.cos(wobP[r][c]);
    }

    // --- collision / snapping ---------------------------------------------
    function collideAt(x, y) {
      for (var r = 0; r < ROWS; r++) {
        for (var c = 0; c < rowCols(r); c++) {
          if (grid[r][c] === null) continue;
          var dx = x - cellX(r, c), dy = y - cellY(r);
          if (dx * dx + dy * dy <= COLLIDE * COLLIDE) return true;
        }
      }
      return false;
    }

    // Nearest empty cell to (x,y): snap to the rounded cell, or breadth-first
    // out from it when that one is taken.
    function snapCell(x, y) {
      var r = clamp(Math.round((y - GRID_TOP - R) / ROWH), 0, ROWS - 1);
      var c = clamp(Math.round((x - R - (isOffset(r) ? R : 0)) / (2 * R)), 0, rowCols(r) - 1);
      if (grid[r][c] === null) return { r: r, c: c };
      var seen = {}, q = [{ r: r, c: c }];
      seen[key(r, c)] = true;
      while (q.length) {
        var cur = q.shift();
        if (validCell(cur.r, cur.c) && grid[cur.r][cur.c] === null) return cur;
        var nb = neighbors(cur.r, cur.c);
        for (var i = 0; i < nb.length; i++) {
          var nr = nb[i][0], nc = nb[i][1];
          if (!validCell(nr, nc)) continue;
          var k = key(nr, nc);
          if (seen[k]) continue;
          seen[k] = true; q.push({ r: nr, c: nc });
        }
      }
      return null;
    }

    /* A film that is still filling is still a BUBBLE: it keeps its colour, and
       a shot that reaches it pops it like any other — which is the whole point
       of the fill taking CONFIG.blightFill seconds rather than being instant.
       Only a film the cloud has finished is out of the game. */
    function isRotten(r, c) { return blk[r][c] && inf[r][c] >= 1; }

    /* Bubbles this shot must not pop. A film the rainbow has just given its
       colour back to is a WIN, not ammunition: popping it in the same breath
       would undo the one thing the cure is for, and the player would see the
       pocket they just cleaned disappear. So the cure marks its bubbles here
       and the flood walks around them — for this shot only (finishShot wipes
       it), which is why they are perfectly ordinary matches the shot after. */
    var spared = {};

    // Same-colour connected group. SUPER and blighted bubbles never take part
    // in a colour match — they only leave the board another way.
    function floodGroup(sr, sc) {
      if (sup[sr][sc] || isRotten(sr, sc) || spared[key(sr, sc)]) return [];
      var color = grid[sr][sc];
      var seen = {}, q = [{ r: sr, c: sc }], group = [];
      seen[key(sr, sc)] = true;
      while (q.length) {
        var cur = q.shift();
        group.push(cur);
        var nb = neighbors(cur.r, cur.c);
        for (var i = 0; i < nb.length; i++) {
          var nr = nb[i][0], nc = nb[i][1];
          if (!validCell(nr, nc) || grid[nr][nc] === null || sup[nr][nc] || isRotten(nr, nc)) continue;
          if (grid[nr][nc] !== color || spared[key(nr, nc)]) continue;
          var k = key(nr, nc);
          if (seen[k]) continue;
          seen[k] = true; q.push({ r: nr, c: nc });
        }
      }
      return group;
    }

    // Everything no longer connected to the ceiling falls.
    function dropFloating() {
      var anchored = {}, q = [];
      for (var c = 0; c < rowCols(0); c++) {
        if (grid[0][c] !== null) { anchored[key(0, c)] = true; q.push({ r: 0, c: c }); }
      }
      while (q.length) {
        var cur = q.shift();
        var nb = neighbors(cur.r, cur.c);
        for (var i = 0; i < nb.length; i++) {
          var nr = nb[i][0], nc = nb[i][1];
          if (!validCell(nr, nc) || grid[nr][nc] === null) continue;
          var k = key(nr, nc);
          if (anchored[k]) continue;
          anchored[k] = true; q.push({ r: nr, c: nc });
        }
      }
      var dropped = [];
      for (var r = 0; r < ROWS; r++) {
        for (var cc = 0; cc < rowCols(r); cc++) {
          if (grid[r][cc] === null || anchored[key(r, cc)]) continue;
          dropped.push({ x: cellX(r, cc), y: cellY(r), color: grid[r][cc], sup: sup[r][cc], blk: blk[r][cc] });
          grid[r][cc] = null; sup[r][cc] = false; blk[r][cc] = false; inf[r][cc] = 0;
        }
      }
      return dropped;
    }

    // --- effects (all through the engine Fx layer) -------------------------
    // A soap bubble does not shatter: the film snaps into a thin expanding
    // ring and throws a spray of droplets, which is what these three lines are.
    function popFx(x, y, idx, isSuper) {
      var base = (idx != null && PAL[idx]) ? PAL[idx] : PAL[0];
      Fx.ring(x, y, { from: R * 0.55, to: R * 1.9, color: isSuper ? "#ffffff" : base.light,
        width: 2, life: 0.26 });
      Fx.burst(x, y, { color: isSuper ? [PAL[0].light, PAL[1].light, PAL[2].light] : base.light,
        count: 7, speed: 250, size: 3.5, life: 0.5, grav: 820 });
      Fx.burst(x, y, { color: "#ffffff", count: 4, speed: 330, size: 2, life: 0.28 });
    }

    // --- launcher / ball ---------------------------------------------------
    // The ball carries its own spring (a/p/ang), because it is the one bubble
    // that is deformed by something other than the board: the launch, the
    // walls it glances off, and the speed it flies at.
    function newBall(colorIndex, isSuper) {
      return { x: LX, y: LY, vx: 0, vy: 0, color: colorIndex, sup: !!isSuper, r: R,
               flying: false, a: 0, p: 0, ang: 0 };
    }
    function updateAimFromPoint(p) {
      var dx = p.x - LX, dy = p.y - LY;
      if (dy > -1) dy = -1;                          // keep the aim upward
      aimAngle = clamp(Math.atan2(dx, -dy), -MAX_AIM, MAX_AIM);
    }
    function fire() {
      if (ball.flying || ended) return;
      ball.vx = Math.sin(aimAngle) * SPEED;
      ball.vy = -Math.cos(aimAngle) * SPEED;
      ball.flying = true;
      // The film is let go: it snaps out along the shot before it settles.
      ball.ang = Math.atan2(ball.vy, ball.vx); ball.a = 0.95; ball.p = Math.PI;
      trail = [];
      shotCount++;
      launchPunch = 1;
      aimLoad = 0;
      if (ball.sup) Sound.clip("shoot", 0.5, 1.2);   // a super leaves the tube brighter
      else Sound.clip("shoot", 0.5, 0.9);
    }

    /* --- THE ROT RACE -----------------------------------------------------
       The round has no clock, so the rot is the clock. It winds up twice
       over: the gap between two ticks closes to `blightRush` of what it
       started at, and a tick that used to take one bubble ends up taking
       `blightBurst`. Both run off the same 0..1 ramp, so there is one number
       to tune and one shape to feel — slow enough to be beaten early, and by
       the end faster than any player can cut it off. */
    function rotRamp() { return clamp(roundT / CONFIG.blightRamp, 0, 1); }
    function rotPeriod() {
      return CONFIG.blightInterval * (1 - rotRamp() * (1 - CONFIG.blightRush));
    }
    function rotBurst() {
      return 1 + Math.floor(rotRamp() * (CONFIG.blightBurst - 1) + 0.001);
    }
    // How much of the wall has turned, counted once a frame: it is the HUD
    // gauge, the vignette, and — at 1 — the end of the round.
    function measureRot() {
      var total = 0, rot = 0;
      for (var r = 0; r < ROWS; r++) {
        var n = rowCols(r);
        for (var c = 0; c < n; c++) {
          // A rainbow does not turn — it is the cure, not a victim — so it is
          // not part of the race either: 100% is every film that CAN rot.
          if (grid[r][c] === null || sup[r][c]) continue;
          total++;
          if (isRotten(r, c)) rot++;
        }
      }
      rotCount = rot; liveCount = total;
      rotPct = total ? rot / total : 0;
    }

    // Contaminate exactly ONE random neighbour of any blighted bubble.
    function spreadBlight() {
      // A target is remembered with the blighted neighbour it came from: that
      // is the side its film gets pierced on, and where the cloud pours in.
      var targets = [], seen = {};
      for (var r = 0; r < ROWS; r++) {
        for (var c = 0; c < rowCols(r); c++) {
          if (!blk[r][c] || grid[r][c] === null || inf[r][c] < 0.8) continue;
          var nb = neighbors(r, c);
          for (var i = 0; i < nb.length; i++) {
            var nr = nb[i][0], nc = nb[i][1];
            if (!validCell(nr, nc)) continue;
            if (grid[nr][nc] === null || blk[nr][nc] || sup[nr][nc]) continue;
            var bk = key(nr, nc);
            if (!seen[bk]) { seen[bk] = true; targets.push([nr, nc, r, c]); }
          }
        }
      }
      if (!targets.length) {
        /* The rot has nowhere to go: the board was dealt clean (LV_OPEN
           seeds: 0, the first two levels, which get CONFIG.rotGrace of it),
           or what is left of it has been cut off from every blighted film.
           Either way a round with the rot for a clock would never end, so it
           breaks out somewhere else instead. */
        if (rotCount < liveCount) {
          seedBlight(1);
          Fx.flash("rgba(150,40,255,0.35)", 0.2);
          /* An EVENT the player did not make: a notice, not a callout. The
             very first rot a player ever meets is named instead (the guide's
             page on it); every outbreak after that is said as what it is. */
          if (!rotCount && !learn("rot", "The rot", "A rotten bubble won't pop. Make it fall or purify it."))
            Notify.say("The rot spreads", { kind: "warn", guide: "outbreak" });
          Sound.clip("spread", 1, 0.55);
        }
        return;
      }
      var pick = Rand.pick(targets);
      // Contaminated at once as far as the rules go — a blighted bubble stops
      // matching the instant it is pierced. The filling below is what the
      // player watches; it never changes what the board does.
      blk[pick[0]][pick[1]] = true;
      inf[pick[0]][pick[1]] = 0;
      var px = cellX(pick[0], pick[1]), py = cellY(pick[0]);
      var sx = cellX(pick[2], pick[3]), sy = cellY(pick[2]);
      var hole = Math.atan2(sy - py, sx - px);
      infAng[pick[0]][pick[1]] = hole;
      // The puncture: a small ring ON THE HOLE, and a puff of the cloud
      // squeezing through it into the film.
      var hx = px + Math.cos(hole) * R * 0.95, hy = py + Math.sin(hole) * R * 0.95;
      Fx.ring(hx, hy, { from: R * 0.06, to: R * 0.9, color: "rgba(190,90,255,0.9)", width: 3, life: 0.4 });
      Fx.burst(hx, hy, { color: ["#8800ff", "#3d0070", "#c050ff"], count: 5, speed: 90, size: 3.5, life: 0.5 });
      // The film turns: a short shudder through the bubbles around it.
      ripple(px, py, 0.30, R * 4.5);
      // A 70 ms tick pitched down to 0.7: quiet in energy but short, so it needs
      // a high gain to sit next to pop/drop without ever masking them.
      Sound.clip("spread", 0.85, 0.7);
    }

    // Simulate the shot for the dotted aim preview (mirrors real flight).
    function simulateShot(angle) {
      var stepLen = R * 0.6;
      var x = LX, y = LY, dx = Math.sin(angle) * stepLen, dy = -Math.cos(angle) * stepLen;
      var pts = [{ x: x, y: y }];
      for (var i = 0; i < 360; i++) {
        x += dx; y += dy;
        if (x - R < 0) { x = R; dx = -dx; }
        else if (x + R > view.w) { x = view.w - R; dx = -dx; }
        if (y - R <= GRID_TOP || collideAt(x, y)) return pts;
        pts.push({ x: x, y: y });
      }
      return pts;
    }

    function comboTier(n) { return n >= 12 ? 3 : n >= 8 ? 2 : n >= 5 ? 1 : 0; }
    // Tier 0 is a plain 3-match: frequent, so it gets the score pop and nothing
    // else. The three tiers above it graduate to a hero callout.
    var TIER_WORD = ["", "Great!", "Awesome!", "Unreal!"];
    var TIER_POP  = ["", "streak", "combo", "ultra"];
    // Tints for the score pop, defined in the SKIN block: blue -> gold -> pink
    // -> blight violet, so the colour alone says how big the clear was.
    var POP_TIER  = ["pop-t0", "pop-t1", "pop-t2", "pop-t3"];

    /* --- THE JOKER --------------------------------------------------------
       A rainbow never matches as itself: it takes a colour, and which colour
       depends on where it is. Sitting in the wall, it takes the colour of the
       bubble that just landed against it — it is the shot that dyes it. Fired
       from the launcher, it has nothing to be dyed by, so it reads the foam it
       landed in and takes the colour its new neighbours share. Either way it
       is a normal bubble by the time the flood runs, which is what lets one
       weld two clusters into a single match. */
    function dominantColor(r, c) {
      var nb = neighbors(r, c), tally = {}, best = null, bestN = 0, i;
      for (i = 0; i < nb.length; i++) {
        var nr = nb[i][0], nc = nb[i][1];
        if (!validCell(nr, nc) || grid[nr][nc] === null) continue;
        if (sup[nr][nc] || isRotten(nr, nc)) continue;
        var v = grid[nr][nc];
        tally[v] = (tally[v] || 0) + 1;
        if (tally[v] > bestN) { bestN = tally[v]; best = v; }
      }
      return best === null ? pickShootColor() : best;
    }
    // The film goes from spectrum to one colour: the rainbow drains into it.
    function prismFx(x, y, idx) {
      var pal = PAL[idx] || PAL[0];
      Fx.ring(x, y, { from: R * 1.5, to: R * 0.45, color: "#ffffff", width: 3, life: 0.3 });
      Fx.burst(x, y, { color: [PAL[0].light, PAL[1].light, PAL[2].light], count: 8,
        speed: 220, size: 3, life: 0.45 });
      Fx.burst(x, y, { color: pal.light, count: 5, speed: 120, size: 3, life: 0.4 });
    }
    function applyJoker(cell) {
      var i, r, c, x, y;
      if (sup[cell.r][cell.c]) {
        var own = dominantColor(cell.r, cell.c);
        grid[cell.r][cell.c] = own; sup[cell.r][cell.c] = false;
        prismFx(cellX(cell.r, cell.c), cellY(cell.r), own);
        chain.joker++;
      }
      var mine = grid[cell.r][cell.c], nb = neighbors(cell.r, cell.c);
      for (i = 0; i < nb.length; i++) {
        r = nb[i][0]; c = nb[i][1];
        if (!validCell(r, c) || grid[r][c] === null || !sup[r][c]) continue;
        grid[r][c] = mine; sup[r][c] = false;
        x = cellX(r, c); y = cellY(r);
        prismFx(x, y, mine);
        setWobble(r, c, 0.95, Math.atan2(cellY(cell.r) - y, cellX(cell.r, cell.c) - x), 0);
        chain.joker++;
      }
    }

    /* --- THE CURE ---------------------------------------------------------
       The other half of the rainbow: thrown into the rot, it gives blighted
       bubbles their colour back. The cure walks THROUGH the foam (a blighted
       bubble with nothing between it and the impact), never across a hole.

       How far it reaches and how many it saves are BOTH read off how much of
       the wall has turned. On a board the rot has barely touched a rainbow
       cleans a pocket of two; on one it has nearly taken, the same bubble —
       well aimed — hands back a quarter of the wall. That is the whole point:
       a rainbow is worth SAVING for the moment it is worth the most, instead
       of being fired the second it is loaded. */
    function cureTargets(cell) {
      var out = [], seen = {}, q = [{ r: cell.r, c: cell.c, d: 0 }], i;
      var k = clamp(rotPct, 0, 1);
      var cap = Math.round(CONFIG.cureMin + (CONFIG.cureMax - CONFIG.cureMin) * k);
      var reach = CONFIG.cureReach + Math.round((CONFIG.cureReachMax - CONFIG.cureReach) * k);
      seen[key(cell.r, cell.c)] = true;
      while (q.length && out.length < cap) {
        var cur = q.shift();
        if (cur.d > 0 && grid[cur.r][cur.c] !== null && blk[cur.r][cur.c])
          out.push({ r: cur.r, c: cur.c });
        if (cur.d >= reach) continue;
        var nb = neighbors(cur.r, cur.c);
        for (i = 0; i < nb.length; i++) {
          var nr = nb[i][0], nc = nb[i][1], k = key(nr, nc);
          if (!validCell(nr, nc) || seen[k] || grid[nr][nc] === null) continue;
          seen[k] = true; q.push({ r: nr, c: nc, d: cur.d + 1 });
        }
      }
      return out;
    }

    /* --- THE CHAIN --------------------------------------------------------
       A cluster used to be wiped in one assignment: the player saw a hole,
       not a clear. It now goes off one bubble at a time, walked outward from
       the bubble that landed, each film popping with its own score — and a
       rainbow's cure runs first, on its own slower cadence, so the beat is
       purify, purify, purify, THEN the match it opened.

       `chain` is the whole of that state: the queue, the cadence, and the
       tally the final callout is written from. update() walks it; a shot that
       lands while one is still running flushes it first (flushChain), so the
       board a new ball snaps into is never half-cleared. */
    function chainOrder(cells, sr, sc) {
      var inSet = {}, out = [], seen = {}, q = [], i, k;
      for (i = 0; i < cells.length; i++) inSet[key(cells[i].r, cells[i].c)] = cells[i];
      k = key(sr, sc);
      if (inSet[k]) { q.push(inSet[k]); seen[k] = true; }
      while (q.length) {
        var cur = q.shift();
        out.push(cur);
        var nb = neighbors(cur.r, cur.c);
        for (i = 0; i < nb.length; i++) {
          var nk = key(nb[i][0], nb[i][1]);
          if (inSet[nk] && !seen[nk]) { seen[nk] = true; q.push(inSet[nk]); }
        }
      }
      // anything the walk never reached goes last rather than never
      for (i = 0; i < cells.length; i++) {
        var ck = key(cells[i].r, cells[i].c);
        if (!seen[ck]) { seen[ck] = true; out.push(cells[i]); }
      }
      return out;
    }

    // Resolve the shot after the ball has snapped into `cell`. NOTHING is
    // cleared here: the shot opens the chain and the update loop walks it.
    function resolveShot(cell) {
      chain = { cell: cell, stage: "", q: [], t: 0, step: POP_STEP,
                gained: 0, popped: 0, cured: 0, joker: 0,
                sx: 0, sy: 0, color: grid[cell.r][cell.c] };
      if (sup[cell.r][cell.c]) {
        var cures = cureTargets(cell);
        if (cures.length) {
          // The rainbow bursts the moment it touches the rot.
          Fx.ring(cellX(cell.r, cell.c), cellY(cell.r),
            { from: R * 0.5, to: R * 4.2, color: "#ffffff", width: 5, life: 0.42 });
          Fx.flash("rgba(255,255,255,0.8)", 0.18);
          Fx.shake(8, 0.26);
          chain.stage = "cure"; chain.q = cures; chain.step = CURE_STEP; chain.t = 0.05;
          return;
        }
      }
      startMatch();
    }

    // The jokers take their colour, then the board is flooded from the impact.
    function startMatch() {
      var cell = chain.cell;
      applyJoker(cell);
      chain.color = grid[cell.r][cell.c];
      var group = floodGroup(cell.r, cell.c);
      if (group.length >= 3) {
        chain.stage = "pop";
        chain.q = chainOrder(group, cell.r, cell.c);
        chain.step = POP_STEP; chain.t = 0;
        return;
      }
      if (chain.cured) { finishClear(); return; }   // a cure is a clear of its own
      // Nothing cleared: the bubble just sticks and the streak resets.
      streak = 0;
      Sound.clip("stick", 0.35, 1.1);                // a dry thud: nothing cleared
      Fx.shake(2, 0.1);
      finishShot();
    }

    // One film, gone. The score it is worth is the streak's, so the whole
    // cluster still totals what it did when it went at once.
    function popOne(it) {
      var r = it.r, c = it.c;
      if (!validCell(r, c) || grid[r][c] === null) return;
      var x = cellX(r, c), y = cellY(r), idx = grid[r][c], wasSuper = sup[r][c];
      popFx(x, y, idx, wasSuper);
      grid[r][c] = null; sup[r][c] = false; blk[r][c] = false; inf[r][c] = 0;
      var n = chain.popped++;
      var gain = 12 * Math.min(streak + 1, 6);
      chain.gained += gain; chain.sx += x; chain.sy += y;
      score += gain; HUD.setScore(score);
      Pop.text(x, y - 12, "+" + gain, { color: (PAL[idx] || PAL[0]).light,
        size: 22, life: 0.6, tier: 1 });
      // Each bubble hands the blow to the foam around it: the hole travels.
      ripple(x, y, 0.34, R * 4.2);
      Fx.shake(Math.min(2 + n * 0.8, 12), 0.12);
      Sound.clip("pop", 0.42, 1 + Math.min(n, 14) * 0.05);   // climbs along the chain
    }

    // One film, given back. The colour is read at the last moment, so a bubble
    // purified a beat ago is already helping the next one pick.
    function cureOne(it) {
      var r = it.r, c = it.c;
      if (!validCell(r, c) || grid[r][c] === null || !blk[r][c]) return;
      var x = cellX(r, c), y = cellY(r);
      var col = dominantColor(r, c);
      blk[r][c] = false; inf[r][c] = 0; grid[r][c] = col;
      spared[key(r, c)] = true;          // it was just saved: it does not pop
      var gain = CONFIG.cureScore;
      chain.cured++; chain.gained += gain;
      score += gain; HUD.setScore(score);
      var pal = PAL[col] || PAL[0];
      Fx.ring(x, y, { from: R * 1.6, to: R * 0.4, color: "#ffffff", width: 3, life: 0.32 });
      Fx.burst(x, y, { color: [pal.light, "#ffffff", pal.core], count: 10, speed: 250,
        size: 3, life: 0.5 });
      Pop.text(x, y - 12, "+" + gain, { color: "#fff3c4", size: 22, life: 0.6, tier: 1 });
      setWobble(r, c, 1.0, Rand.range(0, PI2), 0);
      ripple(x, y, 0.3, R * 4);
      Sound.clip("pop", 0.4, 1.45 + Math.min(chain.cured, 6) * 0.05);
    }

    function stepChain() {
      var it = chain.q.shift();
      chain.t += chain.step;
      if (chain.stage === "cure") cureOne(it); else popOne(it);
    }
    // A queue ran dry: the cure hands over to the match it opened, the pops
    // hand over to the cascade and the callouts.
    function advanceChain() {
      if (chain.stage === "cure") startMatch(); else finishClear();
    }
    // A new shot has landed on a board that is still going off: finish the
    // chain now, with no delay, so nothing resolves against a half-cleared
    // grid. Both stages are the same steps, only without the wait.
    function flushChain() {
      var guard = 0;
      while (chain && guard++ < 600) {
        if (chain.q.length) stepChain(); else advanceChain();
      }
      chain = null;
    }

    // The cluster is gone: what it cut loose falls, and the shot gets its
    // callout — one line for the whole chain, not one per bubble.
    function finishClear() {
      var cleared = chain.popped, mult = Math.min(streak + 1, 6);
      var cx = cleared ? chain.sx / cleared : cellX(chain.cell.r, chain.cell.c);
      var cy = cleared ? chain.sy / cleared : cellY(chain.cell.r);
      var color = chain.color;

      // The hole the cluster left: the foam around it snaps inward and rings
      // out. This is the beat the cascade lands on.
      ripple(cx, cy, 0.65 + Math.min(cleared, 14) * 0.035, R * 9);

      // Cascade: everything cut off from the ceiling falls (and scores).
      var dropped = dropFloating();
      for (var d = 0; d < dropped.length; d++) {
        fallers.push({ x: dropped[d].x, y: dropped[d].y, vx: Rand.range(-70, 70), vy: Rand.range(-40, 40),
          color: dropped[d].color, sup: dropped[d].sup, blk: dropped[d].blk, r: R, life: 2.2,
          a: Rand.range(0.3, 0.6), p: Rand.range(0, PI2), ang: Rand.range(0, PI2) });
      }
      if (dropped.length >= 5) fireworks(dropped);
      var dropGain = dropped.length * 12 * mult;
      score += dropGain; chain.gained += dropGain;
      cleared += dropped.length;
      totalCleared += cleared;
      HUD.setLeft(totalCleared, "Popped");

      // --- scoring ---
      if (chain.popped) streak++;                    // a cure alone keeps the streak
      if (cleared > maxCombo) maxCombo = cleared;
      HUD.setScore(score);
      HUD.punch(chain.cured ? "#ffffff" : (PAL[color] ? PAL[color].core : null));

      // --- impact ---
      // Fx keeps what is positional (burst, ring, freeze); the shake and the
      // full-screen flash of the big beats belong to the Pop style fired just
      // below, so they are not doubled here.
      var mc = PAL[color] || PAL[0];
      var tier = comboTier(cleared);
      if (tier >= 2) {
        Fx.freeze(0.05);
        if (tier === 2) Fx.flash(mc.glow, 0.22);       // tier 3 rides `ultra`'s own flash
        Fx.burst(cx, cy, { color: mc.light, count: 12, speed: 420, size: 3, life: 0.5 });
        Fx.ring(cx, cy, { from: R, to: R * 5, color: mc.light, width: 6, life: 0.5 });
      } else if (tier >= 1) { Fx.flash(mc.glow, 0.15); }

      // --- callouts ---
      // The total pops on the cluster it came from, tinted by the tier; the
      // per-bubble gains have already scrolled up out of it.
      // `cy` can sit right under the ceiling, so hold the pop clear of the HUD.
      var popTier = chain.cured ? 3 : tier;
      Pop.show("score", { word: "+" + chain.gained, cls: POP_TIER[popTier], hold: 160,
                          at: { x: cx, y: Math.max(cy - R - 34, Layout.top + 100) } });
      // The hero line above it only fires once the clear is worth shouting
      // about; a lone streak with a small clear keeps the corner sticker.
      var streakSub = mult > 1 ? "x" + mult + Lang.t(" streak") : cleared + Lang.t(" popped");
      if (chain.cured) {
        Pop.show("combo", { word: "Purified!", sub: chain.cured + Lang.t(" purified"),
                            hold: 420, cls: "pop-cure" });
      } else if (tier >= 1) {
        Pop.show(TIER_POP[tier], { word: TIER_WORD[tier], sub: streakSub,
                                   hold: tier >= 3 ? 420 : 300 });
      } else if (mult > 1) {
        Pop.show("streak", { word: "x" + mult + Lang.t(" streak"), at: "topRight", hold: 260 });
      }

      // --- audio ---
      // Every popped film has already spoken: what is left is the cascade.
      if (dropped.length) Sound.clip("drop", 0.45, 1 + Math.min(dropped.length, 12) * 0.02);

      finishShot();
    }

    // The shot is over, whatever it did: the wall presses, the danger line is
    // read, and the launcher picks what comes after — off the board as it is
    // NOW, which is the point of doing it here and not when the ball landed.
    function finishShot() {
      chain = null;
      spared = {};
      if (ended) return;
      if (shotCount > 0 && shotCount % ADD_SHOTS === 0) pushRow();
      if (lowestBubbleBottom() >= DANGER_Y) { endRun("Overrun!"); return; }
      nextColor = pickShootColor(); nextSuper = Rand.chance(SHOT_SUP);
      if (nextSuper) learn("cure", "Rainbow shot", "Fire a rainbow into the rot to purify it");
    }

    // Fireworks when 5+ bubbles fall at once.
    function fireworks(drops) {
      var pts = drops.slice(0, Math.min(drops.length, 4));
      for (var p = 0; p < pts.length; p++) {
        var fw = pts[p], col = PAL[fw.color] || PAL[p % PAL.length];
        Fx.burst(fw.x, fw.y, { color: [col.core, col.light, "#ffffff"], count: 14, speed: 520, size: 5, life: 0.7, grav: 560 });
        Fx.ring(fw.x, fw.y, { from: R * 0.4, to: R * 5, color: col.glow, width: 5, life: 0.55 });
      }
      Fx.flash(PAL[Rand.int(0, PAL.length - 1)].glow, 0.2);
      // Off in a corner: the cluster already owns the centre this frame.
      Pop.show("bonus", { word: "Cascade", sub: "+" + drops.length + Lang.t(" fell"),
                          at: "lowerLeft", hold: 320 });
      Sound.clip("cheer", 0.5, Rand.range(0.97, 1.05));
    }

    // Push a fresh row in from the top — the pressure that ends the round.
    function pushRow() {
      var bottom = grid[ROWS - 1];
      for (var c0 = 0; c0 < COLS; c0++) if (bottom[c0] !== null) return;  // overflow: danger check handles it
      grid.pop(); sup.pop(); blk.pop(); inf.pop(); infAng.pop();
      wobA.pop(); wobP.pop(); wobAng.pop(); wobD.pop();
      rowShift++;
      var row = [], srow = [], brow = [], irow = [], arow = [];
      var wa = [], wp = [], wg = [], wd = [];
      for (var c = 0; c < COLS; c++) {
        row.push(null); srow.push(false); brow.push(false); irow.push(0); arow.push(0);
        wa.push(0); wp.push(0); wg.push(0); wd.push(0);
      }
      var n = rowCols(0);
      for (var cc = 0; cc < n; cc++) { row[cc] = Rand.int(0, COLORN - 1); srow[cc] = Rand.chance(WALL_SUP); }
      grid.unshift(row); sup.unshift(srow); blk.unshift(brow);
      inf.unshift(irow); infAng.unshift(arow);
      wobA.unshift(wa); wobP.unshift(wp); wobAng.unshift(wg); wobD.unshift(wd);
      fieldY = -ROWH;
      // The whole wall is shoved down: the squeeze runs from the ceiling to the
      // bottom of the stack, one row after the other.
      for (var wr = 0; wr < ROWS; wr++) {
        var wn = rowCols(wr);
        for (var wc = 0; wc < wn; wc++)
          setWobble(wr, wc, 0.52 / (1 + wr * 0.13), Math.PI / 2, wr * 0.028);
      }
      Fx.shake(6, 0.25);
      Sound.clip("press", 0.5, 0.85);                  // the wall grinding one row closer
      for (var sc = 0; sc < n; sc++)
        if (srow[sc]) { learn("joker", "Rainbow bubble", "This bubble will take the right colour"); break; }
    }

    function lowestBubbleBottom() {
      for (var r = ROWS - 1; r >= 0; r--)
        for (var c = 0; c < rowCols(r); c++)
          if (grid[r][c] !== null) return cellY(r) + R;
      return 0;
    }

    // --- lifecycle ---------------------------------------------------------
    function reset() {
      readTunables();
      /* THE BAND FIRST: buildBackground() paints the round over its scene and
         Art.backdrop hands the same picture to the end screen, so the band has
         to be in force before either of them runs. */
      BAND = bandFor();
      Art.backdrop(BAND.scene);
      geometry();
      ROWS = Math.max(10, Math.ceil((Layout.bottom - GRID_TOP) / ROWH) + 2);
      buildSprites();
      buildBackground();     // a no-op on a replay: same band, same frame
      grid = makeGrid(null); sup = makeGrid(false); blk = makeGrid(false);
      inf = makeGrid(0); infAng = makeGrid(0);
      wobA = makeGrid(0); wobP = makeGrid(0); wobAng = makeGrid(0); wobD = makeGrid(0);
      rowShift = 0;
      fillStartRows();
      score = 0;
      aimAngle = 0; aiming = false; aimLoad = 0;
      shotCount = 0; maxCombo = 0; streak = 0;
      ended = false; totalCleared = 0;
      // A board dealt clean waits out its grace before the rot turns up at all.
      blackTimer = (levelOpening() && levelOpening().seeds === 0) ? -CONFIG.rotGrace : 0;
      fallers = []; splashes = []; trail = [];
      bgT = 0; roundT = 0; fieldY = 0; launchPunch = 0; idleTimer = Rand.range(1.5, 3);
      chain = null; spared = {}; swapSpin = 0;
      rotPct = 0; rotCount = 0; liveCount = 0;
      ball = newBall(pickShootColor(), Rand.chance(SHOT_SUP));
      nextColor = pickShootColor(); nextSuper = Rand.chance(SHOT_SUP);
      HUD.setScoreNow(0);
      HUD.setLeft(0, "Popped");
      HUD.setRight(0 + "%", CONFIG.copy.rotLabel, "");
      /* THE BED. The band names the stretch of the track the round rides, so
         replaying a level never restarts the music and crossing into the next
         band does. A playable has no level and a short cut of the track to
         play it on, so `null` — the whole of what this build ships — is the
         right section there. */
      Music.play(CONFIG.level ? BAND.music : null);
      meet();
    }

    /* --- FIRST MEETINGS (web target) ---------------------------------------
       A mechanic the player meets for the first time is NAMED by a notice,
       once per player ever (Notify.learn, packages/shell/shell.js), and its
       line in the "!" log opens the guide's page of the same id — the round
       is never stopped to teach. A playable has no guide, so it says none of
       this and plays as it always has. Only what the frame cannot say is
       named: the swap ring, the rot and the two rainbows. A cascade and the
       wall coming down a row show themselves as they happen. */
    function learn(id, word, sub) {
      return !!window.__GUIDE__ && Notify.learn(id, word, { sub: sub });
    }
    // What the board a round opens on deals: the swap is always there, the
    // rot, a rainbow in the wall and one in the launcher only when dealt.
    function meet() {
      var r, c, rot = false, joker = false;
      learn("swap", "Swap", "Tap the Swap ring to change bubbles");
      for (r = 0; r < ROWS; r++)
        for (c = 0; c < rowCols(r); c++) {
          if (grid[r][c] === null) continue;
          if (blk[r][c]) rot = true;
          if (sup[r][c]) joker = true;
        }
      if (rot) learn("rot", "The rot", "A rotten bubble won't pop. Make it fall or purify it.");
      if (joker) learn("joker", "Rainbow bubble", "This bubble will take the right colour");
      if (ball.sup || nextSuper) learn("cure", "Rainbow shot", "Fire a rainbow into the rot to purify it");
    }

    /* Six levels a band, five bands: the same stretches the level map names on
       its own card. Anything off the map — the endless run above level 30 —
       keeps the last one, and a playable (no level) rides the first. */
    function bandFor() {
      var b = CONFIG.bands;
      if (!CONFIG.level) return b[0];
      return b[clamp(Math.floor((CONFIG.level - 1) / 6), 0, b.length - 1)];
    }

    /* The SWAP: the ring between the loaded bubble and the next one, and the
       next bubble itself — both are the same button, because a thumb aims for
       the bubble it wants and not for the symbol between them. A tap trades
       the two; it costs no shot, so the next bubble is finally worth reading. */
    function inSwapZone(p) {
      var dx = p.x - SWAP_X, dy = p.y - LY;
      if (dx * dx + dy * dy <= SWAP_HIT * SWAP_HIT) return true;
      dx = p.x - NEXT_X; dy = p.y - LY;
      return dx * dx + dy * dy <= NEXT_HIT * NEXT_HIT;
    }
    function doSwap() {
      var c = ball.color, sp = ball.sup;
      ball.color = nextColor; ball.sup = nextSuper;
      nextColor = c; nextSuper = sp;
      swapSpin = 1;
      ball.a = 0.8; ball.p = 0; ball.ang = Math.PI / 2;    // both films take the trade
      Fx.ring(SWAP_X, LY, { from: SWAP_R * 0.4, to: SWAP_R * 2.0,
        color: "rgba(255,255,255,0.65)", width: 2.5, life: 0.26 });
      Sound.clip("stick", 0.3, 1.7);
    }

    function onDown(p) {
      if (ended || ball.flying) return;
      if (inSwapZone(p)) { doSwap(); return; }
      aiming = true; updateAimFromPoint(p);
    }
    function onMove(p) { if (ended || ball.flying || !aiming) return; updateAimFromPoint(p); }
    function onUp(p) {
      if (ended || ball.flying || !aiming) { aiming = false; return; }
      updateAimFromPoint(p); aiming = false; fire();
    }

    function update(dt) {
      bgT += dt;
      if (!ended) roundT += dt;                    // the rot's own clock
      if (launchPunch > 0) launchPunch -= dt * 5;
      if (swapSpin > 0) swapSpin -= dt * 3;
      // The waiting bubble is loaded like a sling while the player aims.
      aimLoad = clamp(aimLoad + (aiming && !ball.flying ? dt * 5 : -dt * 6), 0, 1);
      // The freshly pushed row slides down into place.
      if (fieldY < 0) fieldY = Math.min(0, fieldY + Math.abs(fieldY) * Math.min(1, dt * 16) + dt * 20);
      if (ended) { updateFallers(dt); return; }

      // Every spring on the board: run down its delay, then swing and damp.
      for (var wr = 0; wr < ROWS; wr++) {
        var wn = rowCols(wr);
        for (var wc = 0; wc < wn; wc++) {
          if (wobA[wr][wc] <= 0) continue;
          if (wobD[wr][wc] > 0) { wobD[wr][wc] -= dt; continue; }
          wobP[wr][wc] += OSC_W * dt;
          wobA[wr][wc] *= Math.exp(-OSC_K * dt);
          if (wobA[wr][wc] < 0.004) wobA[wr][wc] = 0;
        }
      }
      // The ball's own spring, same law.
      if (ball.a > 0) {
        ball.p += OSC_W * dt;
        ball.a *= Math.exp(-OSC_K * dt);
        if (ball.a < 0.004) ball.a = 0;
      }
      // Foam is never still: now and then one bubble twitches and the board
      // answers. Costs one pass over the grid every couple of seconds.
      idleTimer -= dt;
      if (idleTimer <= 0) {
        idleTimer = Rand.range(1.6, 3.4);
        var pool = [];
        for (var ir = 0; ir < ROWS; ir++)
          for (var ic = 0; ic < rowCols(ir); ic++)
            if (grid[ir][ic] !== null) pool.push([ir, ic]);
        if (pool.length) {
          var pk = Rand.pick(pool);
          ripple(cellX(pk[0], pk[1]), cellY(pk[0]), 0.17, R * 7);
        }
      }

      // The cloud pouring into every freshly pierced film.
      var fillRate = dt / Math.max(0.1, CONFIG.blightFill);
      for (var ir = 0; ir < ROWS; ir++) {
        var iN = rowCols(ir);
        for (var ic = 0; ic < iN; ic++) {
          if (!blk[ir][ic] || grid[ir][ic] === null || inf[ir][ic] >= 1) continue;
          inf[ir][ic] = Math.min(1, inf[ir][ic] + fillRate);
        }
      }

      // The rot, on its winding-up cadence (see THE ROT RACE).
      blackTimer += dt;
      if (blackTimer >= rotPeriod()) {
        blackTimer = 0;
        for (var sb = 0, sn = rotBurst(); sb < sn; sb++) spreadBlight();
      }

      if (ball.flying) {
        var remaining = dt, maxStep = R / SPEED;   // sub-steps so nothing is missed
        while (ball.flying && remaining > 0) {
          var step = Math.min(remaining, maxStep);
          ball.x += ball.vx * step; ball.y += ball.vy * step;
          remaining -= step;
          if (ball.x - R < 0) {
            ball.x = R; ball.vx = -ball.vx;
            bounceOffWall();
          } else if (ball.x + R > view.w) {
            ball.x = view.w - R; ball.vx = -ball.vx;
            bounceOffWall();
          }
          if (ball.y - R <= GRID_TOP || collideAt(ball.x, ball.y)) { landBall(); break; }
        }
        if (ball.flying) {
          trail.push({ x: ball.x, y: ball.y });
          if (trail.length > 8) trail.shift();
        }
      }

      // THE CHAIN: the cluster the last shot opened, one bubble at a time.
      // A stage that runs dry hands over to the next in the same pass, so a
      // cure that opens a match pops it without a frame of dead air.
      if (chain) {
        chain.t -= dt;
        var guard = 0;
        while (chain && chain.t <= 0 && guard++ < 64) {
          if (chain.q.length) stepChain(); else advanceChain();
        }
      }

      // The two ways this round ends, read once a frame off the same pass.
      measureRot();
      HUD.setRight(Math.round(rotPct * 100) + "%", CONFIG.copy.rotLabel,
                   rotPct >= 0.7 ? "warn" : "");
      if (liveCount > 0 && rotCount >= liveCount) { endRun(CONFIG.copy.rotten); return; }

      // Danger: pulse the overlay glow once the stack creeps down — or once
      // the rot is about to own the wall, whichever is the nearer of the two.
      var near = clamp((lowestBubbleBottom() - (DANGER_Y - 200)) / 200, 0, 1);
      var rotNear = clamp((rotPct - 0.55) / 0.45, 0, 1);
      if (rotNear > near) Overlay.vignette("#a020ff", rotNear * 0.95);
      else Overlay.vignette("#ff4d6d", near * 0.9);

      updateFallers(dt);
    }

    // The film flattens against the wall and springs off it.
    function bounceOffWall() {
      Fx.ring(ball.x, ball.y, { from: R * 0.3, to: R * 1.8, color: "rgba(255,255,255,0.55)", width: 2.5, life: 0.22 });
      ball.a = 0.7; ball.p = 0; ball.ang = 0;          // squeezed across the horizontal
      Sound.clip("stick", 0.22, 1.5);                  // the same thud, glancing off the wall
    }

    function landBall() {
      // Whatever the last shot is still doing, it is done now: the cell this
      // ball snaps into has to be read off a board that has stopped moving.
      if (chain) flushChain();
      if (ended) return;
      var cell = snapCell(ball.x, ball.y);
      if (!cell) { endRun("Overrun!"); return; }
      var lx = cellX(cell.r, cell.c), ly = cellY(cell.r);
      var impactAng = Math.atan2(ball.vy, ball.vx);
      var ballCol = ball.sup ? PAL[0] : (PAL[ball.color] || PAL[0]);
      Fx.ring(lx, ly, { from: R * 0.35, to: R * 2.4, width: 3, life: 0.28,
        color: ball.sup ? "rgba(255,255,255,0.7)" : ballCol.glow });

      grid[cell.r][cell.c] = ball.color;
      sup[cell.r][cell.c] = ball.sup;
      ball.flying = false; trail = [];

      // The cushion: the cluster takes the blow as a wave, and the bubble that
      // just landed is squashed hardest, along the line it came in on.
      ripple(lx, ly, 0.85, R * 8.5);
      setWobble(cell.r, cell.c, 1.15, impactAng, 0);

      // The launcher reloads at once — the chain the shot opened runs on its
      // own, and finishShot() is what presses the wall and picks the next one.
      var nc = nextColor, ns = nextSuper;
      resolveShot(cell);
      if (!ended) ball = newBall(nc, ns);
    }

    /* A cut-off bubble does not slip off the bottom of the screen: it BURSTS
       on the floor of the play area, and pays a bonus for the trip. It is
       what makes a cascade worth watching to the end — the score used to
       arrive with the cut, and everything after it was decoration. A rotten
       one is worth double: the board is rid of it. */
    /* The burst: the film hits, flattens, throws its water up and out along
       the floor and leaves a wet mark that soaks away — and the bonus floats
       off it. The number is kept SMALL and short: a cascade writes one per
       bubble, and at the size of a cluster's own gain they would pile into a
       wall of text over the launcher. */
    function splashFaller(f) {
      var rot = !!f.blk, gain = CONFIG.fallBonus * (rot ? 2 : 1);
      score += gain; HUD.setScore(score);
      var pal = PAL[f.color] || PAL[0];
      var col = rot ? "#c050ff" : pal.light;
      var speed = clamp(f.vy / 900, 0.5, 1.6);          // how hard it came down
      splashes.push({ x: f.x, y: FLOOR_Y, t: 0, life: 0.46,
                      color: col, edge: rot ? "#8800ff" : pal.core, power: speed });
      // the crown: droplets thrown UP off the floor, and a low spray sideways
      Fx.burst(f.x, FLOOR_Y, { color: rot ? ["#c050ff", "#8800ff", "#e0b0ff"] : [pal.light, "#ffffff", pal.core],
        count: Math.round(9 * speed), speed: 300 * speed, size: 3.2, life: 0.42, grav: 1500 });
      Fx.burst(f.x, FLOOR_Y - 2, { color: "#ffffff", count: 5, speed: 420 * speed,
        size: 2, life: 0.24, grav: 900 });
      Fx.ring(f.x, FLOOR_Y, { from: R * 0.2, to: R * 1.25, color: col, width: 3, life: 0.22 });
      // and the floor takes it: a short kick, capped so a ten-bubble cascade
      // shakes once rather than ten times (Fx.shake keeps the loudest).
      Fx.shake(3.5 * speed, 0.14);
      Pop.text(f.x, FLOOR_Y - 30, "+" + gain, { color: rot ? "#d8a6ff" : "#ffffff",
        size: 22, life: 0.6, tier: 1 });
      Sound.clip("pop", 0.3, 1.45 + Rand.range(-0.08, 0.08));
    }

    function updateSplashes(dt) {
      for (var i = splashes.length - 1; i >= 0; i--) {
        splashes[i].t += dt;
        if (splashes[i].t >= splashes[i].life) splashes.splice(i, 1);
      }
    }
    // Flattened rings, drawn ON the floor rather than around a point: the
    // water runs out sideways, so the ellipse is what says "this hit
    // something solid" and a round ring would not.
    function drawSplashes() {
      for (var i = 0; i < splashes.length; i++) {
        var sp = splashes[i], k = sp.t / sp.life, fade = 1 - k;
        var w = R * (0.45 + 2.6 * k) * sp.power;
        ctx.save();
        ctx.translate(sp.x, sp.y);
        ctx.scale(1, 0.30);
        ctx.strokeStyle = rgba(sp.color, 0.85 * fade * fade);
        ctx.lineWidth = 5 * fade + 1;
        ctx.beginPath(); ctx.arc(0, 0, w, 0, PI2); ctx.stroke();
        ctx.strokeStyle = rgba(sp.edge, 0.5 * fade);
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(0, 0, w * 0.62, 0, PI2); ctx.stroke();
        // the wet mark left under it, gone with the ring
        var g = ctx.createRadialGradient(0, 0, 0, 0, 0, w * 0.9);
        g.addColorStop(0, rgba(sp.color, 0.30 * fade));
        g.addColorStop(1, rgba(sp.color, 0));
        ctx.fillStyle = g;
        ctx.beginPath(); ctx.arc(0, 0, w * 0.9, 0, PI2); ctx.fill();
        ctx.restore();
      }
    }

    function updateFallers(dt) {
      for (var i = fallers.length - 1; i >= 0; i--) {
        var f = fallers[i];
        f.x += f.vx * dt; f.y += f.vy * dt; f.vy += 1600 * dt; f.life -= dt;
        // A falling film keeps wobbling, and the fall itself stretches it.
        f.p += OSC_W * 0.75 * dt;
        f.a *= Math.exp(-1.4 * dt);
        f.ang = Math.atan2(f.vy, f.vx);
        // The floor. Once the round is over the score is written and nothing
        // may add to it, so a late faller simply leaves the frame.
        if (!ended && f.y >= FLOOR_Y) { splashFaller(f); fallers.splice(i, 1); continue; }
        if (f.y - f.r > view.h || f.life <= 0) fallers.splice(i, 1);
      }
      updateSplashes(dt);
    }

    /* ---------------- sprite / background caching ---------------- */
    function makeCanvas(w, h) {
      var cv = document.createElement("canvas");
      cv.width = w; cv.height = h;
      return cv;
    }
    var SPR_PAD = 14;                       // room for the halo around the film
    var SPR_UNIT = (R + SPR_PAD) * 2;       // sprite side, in DESIGN px
    // Every sprite is drawn at device resolution — the film's rim is a
    // two-pixel affair and an upscaled one turns to mush.
    function sprCanvas() {
      var dpr = Math.max(1, view.dpr || 1);
      var cv = makeCanvas(Math.ceil(SPR_UNIT * dpr), Math.ceil(SPR_UNIT * dpr));
      var c = cv.getContext("2d");
      c.setTransform(dpr, 0, 0, dpr, 0, 0);
      return c;
    }

    // A SOAP BUBBLE, rendered ONCE. Not a ball: a film. The middle is almost
    // empty and the colour lives in the rim, two iridescent sheens ride the
    // edge, the ground bounces light into the bottom, and one specular window
    // with a crisp dot inside it says "wet". Blitted (and squashed) per frame.
    function makeBubbleSprite(pal) {
      var c = sprCanvas(), cv = c.canvas;
      var x = SPR_UNIT / 2, y = SPR_UNIT / 2;

      // 1. the halo the film throws on the dark ground
      var halo = c.createRadialGradient(x, y, R * 0.84, x, y, R + SPR_PAD);
      halo.addColorStop(0, rgba(pal.core, 0.34));
      halo.addColorStop(0.45, rgba(pal.core, 0.10));
      halo.addColorStop(1, rgba(pal.core, 0));
      c.fillStyle = halo; c.beginPath(); c.arc(x, y, R + SPR_PAD, 0, PI2); c.fill();

      // 2. the film: hollow through the middle, dense and bright at the rim
      var g = c.createRadialGradient(x - R * 0.22, y - R * 0.26, R * 0.05, x, y, R);
      g.addColorStop(0.00, rgba(pal.light, 0.20));
      g.addColorStop(0.32, rgba(pal.core, 0.09));
      g.addColorStop(0.62, rgba(pal.core, 0.26));
      g.addColorStop(0.86, rgba(pal.core, 0.66));
      g.addColorStop(0.955, rgba(pal.light, 0.97));
      g.addColorStop(1.00, rgba(pal.edge, 0.35));
      c.fillStyle = g; c.beginPath(); c.arc(x, y, R, 0, PI2); c.fill();

      // the faint second interference ring, halfway in: what separates a soap
      // film from a glass marble is that the light does not fall off smoothly
      c.save();
      c.globalCompositeOperation = "lighter";
      c.strokeStyle = rgba(pal.light, 0.13); c.lineWidth = R * 0.10;
      c.beginPath(); c.arc(x + R * 0.06, y + R * 0.08, R * 0.52, 0, PI2); c.stroke();
      c.restore();

      // 3. thin-film iridescence — two sheens on the rim, in added light
      c.save();
      c.globalCompositeOperation = "lighter";
      c.lineCap = "round";
      var sheen = c.createLinearGradient(x - R, y + R * 0.2, x + R, y - R * 0.6);
      sheen.addColorStop(0, "rgba(90,255,225,0)");
      sheen.addColorStop(0.30, "rgba(90,255,225,0.62)");
      sheen.addColorStop(0.62, "rgba(180,130,255,0.52)");
      sheen.addColorStop(0.88, "rgba(255,150,220,0.34)");
      sheen.addColorStop(1, "rgba(255,150,220,0)");
      c.strokeStyle = sheen; c.lineWidth = R * 0.19;
      c.beginPath(); c.arc(x, y, R * 0.85, Math.PI * 0.14, Math.PI * 0.98); c.stroke();
      var gold = c.createLinearGradient(x - R * 0.2, y - R, x + R, y + R * 0.2);
      gold.addColorStop(0, "rgba(255,240,180,0)");
      gold.addColorStop(0.45, "rgba(255,226,140,0.55)");
      gold.addColorStop(0.85, "rgba(140,220,255,0.34)");
      gold.addColorStop(1, "rgba(140,220,255,0)");
      c.strokeStyle = gold; c.lineWidth = R * 0.15;
      c.beginPath(); c.arc(x, y, R * 0.88, -Math.PI * 0.52, Math.PI * 0.10); c.stroke();
      // the swirl of the film draining, inside the rim
      c.strokeStyle = "rgba(255,255,255,0.16)"; c.lineWidth = R * 0.07;
      c.beginPath(); c.arc(x - R * 0.1, y + R * 0.12, R * 0.62, Math.PI * 0.25, Math.PI * 0.85); c.stroke();
      c.restore();

      // 4. the light the ground bounces back into the bottom of the film
      c.save();
      c.beginPath(); c.arc(x, y, R, 0, PI2); c.clip();
      var bounce = c.createRadialGradient(x + R * 0.22, y + R * 0.58, 0, x + R * 0.22, y + R * 0.58, R * 0.7);
      bounce.addColorStop(0, rgba(pal.light, 0.34));
      bounce.addColorStop(1, rgba(pal.light, 0));
      c.fillStyle = bounce; c.fillRect(x - R, y, R * 2, R * 1.2);
      c.restore();

      // 5. the specular window, and the hard dot inside it
      c.save();
      c.translate(x - R * 0.36, y - R * 0.40); c.rotate(-0.65); c.scale(1, 0.52);
      var sp = c.createRadialGradient(0, 0, 0, 0, 0, R * 0.34);
      sp.addColorStop(0, "rgba(255,255,255,0.52)");
      sp.addColorStop(0.55, "rgba(255,255,255,0.14)");
      sp.addColorStop(1, "rgba(255,255,255,0)");
      c.fillStyle = sp; c.beginPath(); c.arc(0, 0, R * 0.34, 0, PI2); c.fill();
      c.restore();
      // the hard little window: small, and the only pure white on the film
      c.save();
      c.translate(x - R * 0.40, y - R * 0.44); c.rotate(-0.5); c.scale(1, 0.7);
      c.fillStyle = "rgba(255,255,255,0.92)";
      c.beginPath(); c.arc(0, 0, R * 0.095, 0, PI2); c.fill();
      c.restore();
      return cv;
    }

    // The SUPER: the same film, but the rim runs the whole spectrum — a
    // rainbow band faked with segments, since a conic gradient is not
    // everywhere and this is built once anyway.
    function makeSuperSprite() {
      var c = sprCanvas(), cv = c.canvas;
      var x = SPR_UNIT / 2, y = SPR_UNIT / 2, i;

      var halo = c.createRadialGradient(x, y, R * 0.84, x, y, R + SPR_PAD);
      halo.addColorStop(0, "rgba(255,255,255,0.34)");
      halo.addColorStop(0.5, "rgba(200,180,255,0.12)");
      halo.addColorStop(1, "rgba(255,255,255,0)");
      c.fillStyle = halo; c.beginPath(); c.arc(x, y, R + SPR_PAD, 0, PI2); c.fill();

      // the spectral band on the rim
      var SEG = 30;
      c.save();
      c.lineWidth = R * 0.30;
      for (i = 0; i < SEG; i++) {
        var a0 = (i / SEG) * PI2 - 0.02, a1 = ((i + 1) / SEG) * PI2 + 0.02;
        c.strokeStyle = "hsla(" + Math.round((i / SEG) * 360) + ",100%,72%,0.92)";
        c.beginPath(); c.arc(x, y, R * 0.855, a0, a1); c.stroke();
      }
      c.restore();
      // Keep the middle CLEAR: a hollow film, not a disc. A dark wash here
      // reads as a hole punched in the board, which is the one thing a
      // wildcard must never look like.
      var wash = c.createRadialGradient(x - R * 0.2, y - R * 0.24, 0, x, y, R * 0.78);
      wash.addColorStop(0, "rgba(255,255,255,0.20)");
      wash.addColorStop(0.6, "rgba(255,255,255,0.07)");
      wash.addColorStop(1, "rgba(255,255,255,0)");
      c.save(); c.beginPath(); c.arc(x, y, R, 0, PI2); c.clip();
      c.fillStyle = wash; c.fillRect(x - R, y - R, R * 2, R * 2); c.restore();

      // the white rim that makes it read as the wildcard at a glance
      c.strokeStyle = "rgba(255,255,255,0.92)"; c.lineWidth = R * 0.09;
      c.beginPath(); c.arc(x, y, R * 0.96, 0, PI2); c.stroke();

      c.save();
      c.translate(x - R * 0.34, y - R * 0.38); c.rotate(-0.6); c.scale(1, 0.6);
      var sp = c.createRadialGradient(0, 0, 0, 0, 0, R * 0.44);
      sp.addColorStop(0, "rgba(255,255,255,0.9)");
      sp.addColorStop(1, "rgba(255,255,255,0)");
      c.fillStyle = sp; c.beginPath(); c.arc(0, 0, R * 0.44, 0, PI2); c.fill();
      c.restore();
      c.fillStyle = "rgba(255,255,255,0.95)";
      c.beginPath(); c.arc(x - R * 0.40, y - R * 0.42, R * 0.085, 0, PI2); c.fill();
      return cv;
    }

    // The BLIGHT: the film has gone oily. Same silhouette and the same
    // specular, so it still reads as a bubble — but the colour is a dark gas
    // and the rim is violet.
    function makeBlackSprite() {
      var c = sprCanvas(), cv = c.canvas;
      var x = SPR_UNIT / 2, y = SPR_UNIT / 2, i;
      var aura = c.createRadialGradient(x, y, R * 0.4, x, y, R + SPR_PAD);
      aura.addColorStop(0, "rgba(80,0,160,0.5)"); aura.addColorStop(1, "rgba(10,0,30,0)");
      c.fillStyle = aura; c.beginPath(); c.arc(x, y, R + SPR_PAD, 0, PI2); c.fill();
      var blobs = [[0,0,1.0], [R*-0.18,R*-0.12,0.90], [R*0.15,R*0.09,0.86], [R*-0.10,R*0.17,0.83], [R*0.13,R*-0.17,0.85]];
      for (i = 0; i < blobs.length; i++) {
        var ox = blobs[i][0], oy = blobs[i][1], rs = blobs[i][2];
        var g = c.createRadialGradient(x + ox - R * 0.15, y + oy - R * 0.18, R * 0.08, x + ox, y + oy, R * rs);
        g.addColorStop(0, "rgba(65,0,105,0.92)");
        g.addColorStop(0.5, "rgba(18,0,32,0.96)");
        g.addColorStop(1, "rgba(4,0,8,0)");
        c.fillStyle = g; c.beginPath(); c.arc(x + ox, y + oy, R * rs, 0, PI2); c.fill();
      }
      // the oily sheen of a film that turned
      c.save();
      c.globalCompositeOperation = "lighter";
      var oil = c.createLinearGradient(x - R, y + R * 0.3, x + R, y - R * 0.5);
      oil.addColorStop(0, "rgba(0,255,180,0)");
      oil.addColorStop(0.4, "rgba(90,255,190,0.20)");
      oil.addColorStop(0.8, "rgba(200,80,255,0.26)");
      oil.addColorStop(1, "rgba(200,80,255,0)");
      c.strokeStyle = oil; c.lineWidth = R * 0.16; c.lineCap = "round";
      c.beginPath(); c.arc(x, y, R * 0.86, Math.PI * 0.16, Math.PI * 0.96); c.stroke();
      c.restore();
      c.strokeStyle = "rgba(150,40,255,0.55)"; c.lineWidth = 2.5;
      c.beginPath(); c.arc(x, y, R * 0.9, 0, PI2); c.stroke();
      var core = c.createRadialGradient(x, y, 0, x, y, R * 0.52);
      core.addColorStop(0, "rgba(170,50,255,0.22)"); core.addColorStop(1, "rgba(170,50,255,0)");
      c.fillStyle = core; c.beginPath(); c.arc(x, y, R * 0.52, 0, PI2); c.fill();
      c.fillStyle = "rgba(210,180,255,0.55)";
      c.beginPath(); c.arc(x - R * 0.40, y - R * 0.42, R * 0.075, 0, PI2); c.fill();
      return cv;
    }
    // One puff of the cloud: four soft lobes and a violet ember, so a blob of
    // it has smoke edges. Blitted at whatever size a puff has grown to.
    function makePuffSprite() {
      var c = sprCanvas(), cv = c.canvas, i;
      var x = SPR_UNIT / 2, y = SPR_UNIT / 2;
      var lob = [[0, 0, 1.00], [-0.22, -0.14, 0.72], [0.20, 0.16, 0.66], [0.12, -0.20, 0.60]];
      for (i = 0; i < lob.length; i++) {
        var ox = lob[i][0] * R, oy = lob[i][1] * R, rr = R * lob[i][2];
        var g = c.createRadialGradient(x + ox, y + oy, 0, x + ox, y + oy, rr);
        g.addColorStop(0, "rgba(46,0,78,0.95)");
        g.addColorStop(0.45, "rgba(22,0,42,0.72)");
        g.addColorStop(1, "rgba(10,0,20,0)");
        c.fillStyle = g; c.beginPath(); c.arc(x + ox, y + oy, rr, 0, PI2); c.fill();
      }
      var e = c.createRadialGradient(x, y, 0, x, y, R * 0.5);
      e.addColorStop(0, "rgba(150,40,255,0.30)"); e.addColorStop(1, "rgba(150,40,255,0)");
      c.fillStyle = e; c.beginPath(); c.arc(x, y, R * 0.5, 0, PI2); c.fill();
      return cv;
    }
    function freeSprites() {
      if (bubbleSprites)
        for (var i = 0; i < bubbleSprites.length; i++) freeCanvas(bubbleSprites[i]);
      bubbleSprites = null;
      superSprite = freeCanvas(superSprite);
      blackSprite = freeCanvas(blackSprite);
      puffSprite = freeCanvas(puffSprite);
    }
    // The sprites depend on the palette and the bubble size (CONFIG constants)
    // and on the device resolution they are rendered at — nothing else.
    function buildSprites() {
      var sig = String(Math.max(1, view.dpr || 1));
      if (bubbleSprites && sig === sprSig) return;
      freeSprites();
      sprSig = sig;
      bubbleSprites = [];
      for (var i = 0; i < PAL.length; i++) bubbleSprites.push(makeBubbleSprite(PAL[i]));
      superSprite = makeSuperSprite();
      blackSprite = makeBlackSprite();
      puffSprite = makePuffSprite();
    }
    function buildBackground() {
      /* THE SCENE OF THE BAND. One of the five paintings of CONFIG.art, and
         the same one the end screen wears (Art.backdrop, above) — not a
         picture of its own: the round and the screen it ends on are the same
         place. `Art.sceneKey()` is the fallback for anything with no band —
         the intro's own scene, which is also the only one a playable ships. */
      var key = (BAND && BAND.scene && ArtImages[BAND.scene]) ? BAND.scene : Art.sceneKey();
      var img = ArtImages[key];
      // The frame, the HUD band it darkens, which painting and whether it has
      // decoded yet — a scene that lands late is picked up on the next round.
      var sig = view.w + "x" + view.h + "|" + Layout.top + "|" + key + "|" +
                (img && img.width ? 1 : 0);
      if (bgCanvas && sig === bgSig) return;
      bgCanvas = freeCanvas(bgCanvas);
      bgSig = sig;
      bgCanvas = makeCanvas(view.w, view.h);
      var c = bgCanvas.getContext("2d");
      if (img && img.width) {
        // Cover-fit the painted scene to the design canvas (crop, no stretch).
        var s = Math.max(view.w / img.width, view.h / img.height);
        var dw = img.width * s, dh = img.height * s;
        c.drawImage(img, (view.w - dw) / 2, (view.h - dh) / 2, dw, dh);
      } else {
        var g = c.createLinearGradient(0, 0, 0, view.h);
        g.addColorStop(0, "#231a4a"); g.addColorStop(1, "#0b0820");
        c.fillStyle = g; c.fillRect(0, 0, view.w, view.h);
      }
      // Darken behind the HUD so the score always reads clearly.
      var band = Layout.top + 60;
      var tg = c.createLinearGradient(0, 0, 0, band);
      tg.addColorStop(0, "rgba(0,0,0,0.55)"); tg.addColorStop(1, "rgba(0,0,0,0)");
      c.fillStyle = tg; c.fillRect(0, 0, view.w, band);
      // Gentle vignette to focus the play area.
      var vg = c.createRadialGradient(view.w / 2, view.h * 0.5, view.h * 0.34, view.w / 2, view.h * 0.5, view.h * 0.82);
      vg.addColorStop(0, "rgba(0,0,0,0)"); vg.addColorStop(1, "rgba(0,0,0,0.42)");
      c.fillStyle = vg; c.fillRect(0, 0, view.w, view.h);
    }

    /* ---------------- rendering (blit-based, cheap) ---------------- */
    /* One bubble. `def` is the film's deformation: > 0 squashes it across
       `defAng` and stretches it along the perpendicular, < 0 does the reverse
       (which is how the flying ball is drawn elongated on its own flight).
       The sprite is rotated back out of the squash frame, so the specular
       highlight stays where the light is instead of tumbling with the axis. */
    /* Put the context INTO one bubble's frame — its squash, its breathing, its
       place on the board — with (0,0) at its centre. Everything drawn after it
       rides the deformation, which is what lets the contamination fill a film
       that is itself being squeezed. Always paired with ctx.restore(). */
    function enterBubble(x, y, r, def, defAng, puff) {
      ctx.save();
      ctx.translate(x, y);
      if (def && (def > 0.003 || def < -0.003)) {
        ctx.rotate(defAng);
        ctx.translate(def * r * 0.10, 0);            // shoved a little along the blow
        ctx.scale(1 - def * SQ, 1 + def * ST);
        ctx.rotate(-defAng);
      }
      if (puff && puff !== 1) ctx.scale(puff, puff);
    }
    function drawBubble(x, y, r, idx, isSuper, isBlack, alpha, rot, def, defAng, puff) {
      var spr = isBlack ? blackSprite : (isSuper ? superSprite : bubbleSprites[idx]);
      if (!spr) return;
      var w = SPR_UNIT * (r / R), half = w / 2;
      enterBubble(x, y, r, def, defAng, puff);
      if (alpha != null && alpha < 1) ctx.globalAlpha = alpha;
      if (rot) ctx.rotate(rot);
      ctx.drawImage(spr, -half, -half, w, w);
      ctx.restore();
    }

    /* A film being contaminated. The bubble is still its own colour; the cloud
       comes in through ONE point of the rim — the side the blighted neighbour
       is on — and billows inward until it owns the whole thing. The lobes are
       what keeps it from reading as a disc growing on a timer, and they are
       clipped to the film, so the smoke is inside the bubble and not on it. */
    function drawInfecting(x, y, r, idx, def, defAng, puff, t, holeAng, seed) {
      var i;
      // A film with something pouring into it shivers: a faster tremor on top
      // of the board's breathing, gone by the time it is full.
      puff = puff * (1 + 0.022 * (1 - t) * Math.sin(bgT * 9.5 + seed));
      drawBubble(x, y, r, idx, false, false, 1, 0, def, defAng, puff);
      // the halo of the finished blight, faded in over the last of the fill,
      // so nothing pops when the cell switches to the plain sprite at t = 1
      if (t > 0.85) drawBubble(x, y, r, idx, false, true, (t - 0.85) / 0.15, 0, def, defAng, puff);

      var hx = Math.cos(holeAng) * r * 0.95, hy = Math.sin(holeAng) * r * 0.95;
      var dir = holeAng + Math.PI;                     // in, toward the far side
      enterBubble(x, y, r, def, defAng, puff);
      ctx.beginPath(); ctx.arc(0, 0, r * 0.985, 0, PI2); ctx.clip();   // inside the film
      // Five puffs strung from the hole to the far rim. `reach` is how far the
      // cloud has got (in radii); a puff nearer than that has arrived and is
      // swelling, one beyond it has not come through yet — which is what reads
      // as smoke pouring in rather than a disc growing on a timer.
      var reach = 2.05 * t;
      for (i = 0; i < 5; i++) {
        var at = (i / 4) * 2.0;
        if (at > reach) break;
        var grow = clamp((reach - at) * 1.5, 0, 1);
        var sway = 0.16 * r * Math.sin(bgT * 1.9 + seed + i * 1.3);
        var px = hx + Math.cos(dir) * at * r - Math.sin(dir) * sway;
        var py = hy + Math.sin(dir) * at * r + Math.cos(dir) * sway;
        var pr = r * (0.26 + 0.46 * grow) * (1 + 0.07 * Math.sin(bgT * 2.6 + i * 2.1));
        var pw = SPR_UNIT * (pr / R);
        ctx.globalAlpha = (0.55 + 0.45 * grow) * Math.min(1, 0.35 + t * 2);
        ctx.drawImage(puffSprite, px - pw / 2, py - pw / 2, pw, pw);
      }
      ctx.restore();

      // the puncture itself: a violet pinprick on the rim, brightest while the
      // cloud is still squeezing through it
      var spark = (1 - t) * (0.55 + 0.45 * Math.sin(bgT * 14 + seed));
      if (spark > 0.02) {
        enterBubble(x, y, r, def, defAng, puff);
        var g = ctx.createRadialGradient(hx, hy, 0, hx, hy, r * 0.30);
        g.addColorStop(0, "rgba(235,190,255," + (0.85 * spark).toFixed(3) + ")");
        g.addColorStop(0.45, "rgba(150,40,255," + (0.45 * spark).toFixed(3) + ")");
        g.addColorStop(1, "rgba(150,40,255,0)");
        ctx.fillStyle = g;
        ctx.beginPath(); ctx.arc(hx, hy, r * 0.30, 0, PI2); ctx.fill();
        ctx.restore();
      }
    }

    function render() {
      ctx.drawImage(bgCanvas, 0, 0, view.w, view.h);
      drawDangerLine();

      // Grid bubbles: the push-down slide, the spring each one is on, and the
      // slow breathing that keeps a settled board alive.
      ctx.save();
      ctx.translate(0, fieldY);
      var superRot = bgT * 0.6;
      for (var r = 0; r < ROWS; r++) {
        var n = rowCols(r);
        for (var c = 0; c < n; c++) {
          if (grid[r][c] === null) continue;
          var phase = r * 1.7 + c * 2.9;
          var puff = 1 + BREATHE * Math.sin(bgT * 1.5 + phase);
          var def = deformAt(r, c);
          // Every bubble, the smoke, the controls and the shot are the
          // elements of the round's entrance (Enter): the wall rains in first.
          if (!Enter.begin(cellX(r, c), cellY(r))) continue;
          if (blk[r][c] && inf[r][c] < 1) {
            drawInfecting(cellX(r, c), cellY(r), R, grid[r][c], def, wobAng[r][c], puff,
                          inf[r][c], infAng[r][c], phase);
          } else {
            drawBubble(cellX(r, c), cellY(r), R, grid[r][c], sup[r][c], blk[r][c], 1,
                       sup[r][c] ? superRot : 0, def, wobAng[r][c], puff);
          }
          Enter.end();
        }
      }
      ctx.restore();

      if (Enter.begin(view.w / 2, fieldY + GRID_TOP + ROWH * 3)) { drawBlightSmoke(); Enter.end(); }

      for (var fi = 0; fi < fallers.length; fi++) {
        var f = fallers[fi];
        drawBubble(f.x, f.y, f.r, f.color, f.sup, f.blk, clamp(f.life, 0, 1), 0,
                   f.a * Math.cos(f.p), f.ang, 1);
      }

      drawSplashes();

      // The preview comes first so the shot lands last; the two never overlap.
      if (Enter.begin(NEXT_X, LY)) { drawNextPreview(); Enter.end(); }
      if (Enter.begin(LX, LY)) {
        if (!ball.flying && !ended) drawAim();
        drawLauncher();
        Enter.end();
      }
      if (!ball.flying && !ended && Enter.begin(SWAP_X, LY)) { drawSwapRing(); Enter.end(); }
      if (ball.flying) drawTrail();
      if (!ended && Enter.begin(ball.x, ball.y)) { drawBall(); Enter.end(); }
    }

    // The shot itself: stretched along its flight the way a water balloon is,
    // plus whatever its own spring is still doing after a launch or a bounce.
    function drawBall() {
      var def, ang;
      if (ball.flying) {
        var spd = Math.sqrt(ball.vx * ball.vx + ball.vy * ball.vy);
        ang = Math.atan2(ball.vy, ball.vx);
        def = -0.42 * clamp(spd / SPEED, 0, 1) + ball.a * Math.cos(ball.p) * 0.9;
      } else {
        // Waiting on the launcher: loaded like a sling while the player aims.
        ang = aimAngle - Math.PI / 2;
        def = aimLoad * 0.13 + ball.a * Math.cos(ball.p);
      }
      var puff = 1 + BREATHE * 1.6 * Math.sin(bgT * 2.2);
      drawBubble(ball.x, ball.y, R, ball.color, ball.sup, false, 1,
                 ball.sup ? bgT * 0.6 : 0, def, ang, puff);
    }

    // Animated smoke aura around blighted bubbles (drawn live: it is cheap).
    function drawBlightSmoke() {
      ctx.save();
      ctx.translate(0, fieldY);
      for (var r = 0; r < ROWS; r++) {
        for (var c = 0; c < rowCols(r); c++) {
          if (!blk[r][c] || grid[r][c] === null) continue;
          // Nothing escapes a film that is not full yet: the outside smoke
          // comes in with the cloud.
          var lvl = inf[r][c];
          if (lvl <= 0.05) continue;
          var bx = cellX(r, c), by = cellY(r), phase = r * 2.3 + c * 5.7;
          var auraR = R * (1.06 + 0.09 * Math.sin(bgT * 2.4 + phase));
          ctx.globalAlpha = (0.18 + 0.07 * Math.sin(bgT * 2.1 + phase)) * lvl;
          ctx.fillStyle = "#4a0090";
          ctx.beginPath(); ctx.arc(bx, by, auraR, 0, PI2); ctx.fill();
          for (var w = 0; w < 3; w++) {
            var a = (w / 3) * PI2 + bgT * (0.9 + w * 0.22) + phase;
            var dist = R * (0.6 + 0.14 * Math.sin(bgT * 1.7 + w * 1.3));
            var wr = R * (0.19 + 0.08 * Math.sin(bgT * 2.5 + w));
            ctx.globalAlpha = (0.28 + 0.1 * Math.sin(bgT * 1.9 + w * 0.8)) * lvl;
            ctx.fillStyle = w === 0 ? "#8800ff" : (w === 1 ? "#3d0070" : "#c050ff");
            ctx.beginPath(); ctx.arc(bx + Math.cos(a) * dist, by + Math.sin(a) * dist * 0.82, wr, 0, PI2); ctx.fill();
          }
        }
      }
      ctx.globalAlpha = 1;
      ctx.restore();
    }

    // The wet smear the film drags behind it: ellipses pinched across the
    // flight, not the round dots a marble would leave.
    function drawTrail() {
      var col = PAL[ball.color] || PAL[0];
      var ang = Math.atan2(ball.vy, ball.vx);
      ctx.save();
      ctx.fillStyle = ball.sup ? "#ffffff" : col.light;
      for (var i = 0; i < trail.length; i++) {
        var k = i / trail.length;
        ctx.globalAlpha = k * 0.26;
        ctx.save();
        ctx.translate(trail[i].x, trail[i].y);
        ctx.rotate(ang);
        ctx.scale(1 + 0.5 * k, 0.46);
        ctx.beginPath(); ctx.arc(0, 0, R * (0.3 + 0.55 * k), 0, PI2); ctx.fill();
        ctx.restore();
      }
      ctx.restore();
      ctx.globalAlpha = 1;
    }

    // Dotted trajectory only — no ghost bubble at the landing spot.
    function drawAim() {
      var pts = simulateShot(aimAngle);
      ctx.fillStyle = "#ffffff";
      for (var i = 0; i < pts.length; i += 3) {
        ctx.globalAlpha = 0.5 * (1 - i / pts.length);
        ctx.beginPath(); ctx.arc(pts[i].x, pts[i].y, 4, 0, PI2); ctx.fill();
      }
      ctx.globalAlpha = 1;
    }

    function drawLauncher() {
      var punch = launchPunch > 0 ? launchPunch : 0;
      var ring = (R + 16) * (1 - punch * 0.12) * (1 + 0.012 * Math.sin(bgT * 2.6));
      ctx.strokeStyle = "rgba(255,255,255,0.25)";
      ctx.lineWidth = 3;
      ctx.beginPath(); ctx.arc(LX, LY, ring, 0, PI2); ctx.stroke();
    }

    /* The swap button: a ring with two arrows chasing each other round it,
       sat between the two bubbles it trades. It spins down after a trade
       rather than animating for ever — an idle control that moves pulls the
       eye away from the board. */
    function drawSwapRing() {
      var t = swapSpin > 0 ? swapSpin : 0;
      var rr = SWAP_R * (1 + 0.16 * t), i;
      ctx.save();
      ctx.translate(SWAP_X, LY);
      ctx.rotate(t * Math.PI * 1.6);
      ctx.lineCap = "round";
      ctx.lineWidth = 2.5;
      ctx.strokeStyle = "rgba(255,255,255," + (0.16 + 0.22 * t).toFixed(3) + ")";
      ctx.beginPath(); ctx.arc(0, 0, rr, 0, PI2); ctx.stroke();
      ctx.strokeStyle = "rgba(255,255,255," + (0.42 + 0.45 * t).toFixed(3) + ")";
      ctx.lineWidth = 3;
      for (i = 0; i < 2; i++) {
        var a0 = i * Math.PI + 0.30, a1 = i * Math.PI + Math.PI - 0.60;
        var ar = rr * 0.60;
        ctx.beginPath(); ctx.arc(0, 0, ar, a0, a1); ctx.stroke();
        // the head, laid back along the arc it ends
        var hx = Math.cos(a1) * ar, hy = Math.sin(a1) * ar, back = a1 - Math.PI / 2;
        ctx.beginPath();
        ctx.moveTo(hx + Math.cos(back - 0.55) * 10, hy + Math.sin(back - 0.55) * 10);
        ctx.lineTo(hx, hy);
        ctx.lineTo(hx + Math.cos(back + 0.55) * 10, hy + Math.sin(back + 0.55) * 10);
        ctx.stroke();
      }
      ctx.restore();
    }

    function drawNextPreview() {
      var nx = NEXT_X, ny = LY, nr = R * 0.6;
      ctx.fillStyle = "rgba(255,255,255,0.55)";
      ctx.font = "bold 18px -apple-system,Segoe UI,Roboto,sans-serif";
      ctx.textAlign = "center";
      ctx.fillText(upper(Lang.t("Next")), nx, ny - nr - 12);
      ctx.textAlign = "left";
      drawBubble(nx, ny, nr, nextColor, nextSuper, false, 1, 0, 0, 0,
                 1 + BREATHE * 1.4 * Math.sin(bgT * 1.9 + 1.1));
    }

    function drawDangerLine() {
      var closeness = clamp((lowestBubbleBottom() - (DANGER_Y - 260)) / 260, 0, 1);
      if (closeness <= 0.02) return;
      var pulse = 0.35 + 0.35 * Math.abs(Math.sin(bgT * 4));
      ctx.save();
      ctx.globalAlpha = closeness * pulse;
      ctx.strokeStyle = "#ff4d6d";
      ctx.lineWidth = 3;
      ctx.setLineDash([14, 10]);
      ctx.beginPath(); ctx.moveTo(0, DANGER_Y); ctx.lineTo(view.w, DANGER_Y); ctx.stroke();
      ctx.restore();
    }

    /* --- the guide: every rule, as pages (packages/webshell/guide.js) -----
       Every page SHOWS before it tells, and every picture is painted by the
       round's own renderer: drawBubble, drawInfecting, drawLauncher and
       drawSwapRing are lent a canvas of their own for the length of the call
       (the round's `ctx` is swapped and given back), so a bubble read in the
       guide is the bubble on the wall, sprite for sprite. The guide can open
       before any round — from the Help card on the title screen — so nothing
       here reads the board: a picture is a patch of wall written out by hand,
       and the figures are read off CONFIG and the manifest's level tuning. */
    var SQ3 = Math.sqrt(3);
    function paintPic(W, H, fn) {
      if (!LY) geometry();                    // derived from Layout alone
      buildSprites();                         // a cache: a no-op once built
      var cv = document.createElement("canvas"), k = view.dpr || 1, keep = ctx, keepT = bgT;
      cv.width = Math.round(W * k); cv.height = Math.round(H * k);
      cv.style.width = W + "px"; cv.style.height = H + "px";
      ctx = cv.getContext("2d"); ctx.scale(k, k);
      if (keepT == null) bgT = 0;             // drawInfecting reads the board's clock
      try { fn(); } finally { ctx = keep; bgT = keepT; }
      return cv;
    }
    /* One bubble of a picture. `b` is a palette index, "s" a rainbow, "x" a
       rotten film, or { c, t, hole } a film the cloud is still filling. */
    function picBubble(x, y, b, r, alpha, def, ang) {
      r = r || R;
      if (b === "s") drawBubble(x, y, r, 0, true, false, alpha, 0.6, def || 0, ang || 0, 1);
      else if (b === "x") {
        // drawBlightSmoke's aura, held still: on the board it is what makes
        // a rotten film read against a dark scene, and a picture needs it more
        ctx.save();
        ctx.globalAlpha = 0.5 * (alpha == null ? 1 : alpha); ctx.fillStyle = "#4a0090";
        ctx.beginPath(); ctx.arc(x, y, r * 1.1, 0, PI2); ctx.fill();
        ctx.globalAlpha = 0.7 * (alpha == null ? 1 : alpha); ctx.strokeStyle = "#c050ff"; ctx.lineWidth = Math.max(1.5, r * 0.08);
        ctx.beginPath(); ctx.arc(x, y, r * 0.98, 0, PI2); ctx.stroke();
        ctx.restore();
        drawBubble(x, y, r, 0, false, true, alpha, 0, def || 0, ang || 0, 1);
      }
      else if (typeof b === "object") drawInfecting(x, y, r, b.c, 0, 0, 1, b.t, b.hole, 1.3);
      else drawBubble(x, y, r, b, false, false, alpha, 0, def || 0, ang || 0, 1);
    }
    /* A patch of wall written as rows of letters — r y b the three colours,
       s a rainbow, x a rotten film, . a hole — with every odd row half a
       bubble in, the way the board staggers them. (x0, y0) is the top-left
       of the first row's first bubble. */
    var PIC_CH = { r: 0, y: 1, b: 2, s: "s", x: "x" };
    function picWall(rows, x0, y0, r) {
      r = r || R;
      var out = [];
      for (var i = 0; i < rows.length; i++)
        for (var j = 0; j < rows[i].length; j++) {
          var ch = rows[i].charAt(j);
          if (PIC_CH[ch] == null) continue;
          var p = picCell(x0, y0, i, j, r);
          picBubble(p.x, p.y, PIC_CH[ch], r);
          out.push(p);
        }
      return out;
    }
    function picCell(x0, y0, i, j, r) {
      r = r || R;
      return { x: x0 + r + j * 2 * r + (i % 2 ? r : 0), y: y0 + r + i * r * SQ3 };
    }
    // The aim line, in drawAim's own dots: one every three steps of the real
    // preview, fading out along the line, bouncing once off a side.
    function picDots(pts) {
      ctx.fillStyle = "#ffffff";
      for (var i = 0; i < pts.length; i += 3) {
        ctx.globalAlpha = 0.5 * (1 - i / pts.length);
        ctx.beginPath(); ctx.arc(pts[i].x, pts[i].y, 4, 0, PI2); ctx.fill();
      }
      ctx.globalAlpha = 1;
    }
    // simulateShot's walk, against the picture's own sides and wall
    function picPath(x, y, ang, wall, side0, side1) {
      var pts = [], st = R * 0.6, dx = Math.sin(ang) * st, dy = -Math.cos(ang) * st, i, j;
      for (i = 0; i < 120 && y > R; i++) {
        pts.push({ x: x, y: y });
        x += dx; y += dy;
        if (x < side0) { x = side0; dx = -dx; } else if (x > side1) { x = side1; dx = -dx; }
        for (j = 0; j < wall.length; j++) {
          var ex = x - wall[j].x, ey = y - wall[j].y;
          if (ex * ex + ey * ey <= COLLIDE * COLLIDE) return pts;
        }
      }
      return pts;
    }
    // The launcher and its swap ring, drawn where the picture wants them:
    // both draw at the round's own launcher row, so the context is moved.
    function picLauncher(x, y) {
      ctx.save(); ctx.translate(x - LX, y - LY); drawLauncher(); ctx.restore();
    }
    function picSwapRing(x, y) {
      ctx.save(); ctx.translate(x - SWAP_X, y - LY); drawSwapRing(); ctx.restore();
    }
    // drawNextPreview's own label and bubble, at a point of the picture.
    function picNext(x, y, b) {
      var nr = R * 0.6;
      ctx.fillStyle = "rgba(255,255,255,0.55)";
      ctx.font = "bold 18px -apple-system,Segoe UI,Roboto,sans-serif";
      ctx.textAlign = "center";
      ctx.fillText(upper(Lang.t("Next")), x, y - nr - 12);
      ctx.textAlign = "left";
      picBubble(x, y, b, nr);
    }
    // drawDangerLine's dashes, at full strength.
    function picDanger(W, y) {
      ctx.save();
      ctx.globalAlpha = 0.7; ctx.strokeStyle = "#ff4d6d"; ctx.lineWidth = 3;
      ctx.setLineDash([14, 10]);
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(W, y); ctx.stroke();
      ctx.restore();
    }

    // A figure in the player's own decimal mark.
    function num(v) {
      var s = String(Math.round(v * 10) / 10);
      return Lang.code() === "fr" ? s.replace(".", ",") : s;
    }
    function fill(str, vars) {
      return String(str).replace(/\{(\w+)\}/g, function (m, k) { return vars[k] != null ? vars[k] : m; });
    }

    /* A band's picture: its own scene, and over it the board one of its
       levels opens on (LV_OPEN), dealt the way fillStartRows deals it — the
       figure, its colour pattern, what it leaves hanging pruned, its rot
       seeds — at half size. The two patterns that roll dice are dealt off a
       fixed hash instead, so the picture is the same every time it opens. */
    function bandPic(b, lvl) {
      var W = 400, H = 220, rr, open = LV_OPEN[lvl - 1];
      var art = open.art ? LV_ART[open.art] : null, rows = art ? art.rows : open.rows;
      var half = view.w / 2, spanX = half - R, k = Math.min(open.colors, PAL.length);
      var cells = {}, list = [], r, c, i;
      for (r = 0; r < rows; r++) {
        var n = r % 2 ? COLS - 1 : COLS, v = rows > 1 ? r / (rows - 1) : 0;
        for (c = 0; c < n; c++) {
          var bx = R + c * 2 * R + (r % 2 ? R : 0);
          if (art && !(art.cell ? art.cell(r, c) : art.hit((bx - half) / spanX, v))) continue;
          var col = open.fill === "random" ? (r * 7 + c * 5 + (r * c) % 3) % k
                  : open.fill === "clusters" ? (((r >> 1) * 8 + Math.floor(c / 3)) * 7 + 1) % k
                  : patternColor(open.fill, r, c, k);
          cells[r + "_" + c] = col;
        }
      }
      // what hangs from nothing goes, as pruneFloating does it (row parity is
      // the board's own at the start of a round)
      var ok = {}, q = [];
      for (c = 0; c < COLS; c++) if (cells["0_" + c] != null) { ok["0_" + c] = 1; q.push([0, c]); }
      while (q.length) {
        var cur = q.pop(), o = cur[0] % 2 === 1, rr0 = cur[0], cc0 = cur[1];
        var nb = o ? [[rr0, cc0 - 1], [rr0, cc0 + 1], [rr0 - 1, cc0], [rr0 - 1, cc0 + 1], [rr0 + 1, cc0], [rr0 + 1, cc0 + 1]]
                   : [[rr0, cc0 - 1], [rr0, cc0 + 1], [rr0 - 1, cc0 - 1], [rr0 - 1, cc0], [rr0 + 1, cc0 - 1], [rr0 + 1, cc0]];
        for (i = 0; i < nb.length; i++) {
          var kk = nb[i][0] + "_" + nb[i][1];
          if (cells[kk] != null && !ok[kk]) { ok[kk] = 1; q.push(nb[i]); }
        }
      }
      for (var key2 in cells) if (ok[key2]) list.push(key2);
      for (i = 0; i < open.seeds && list.length; i++)
        cells[list[Math.floor((i + 0.5) * list.length / open.seeds)]] = "x";
      return paintPic(W, H, function () {
        var img = ArtImages[CONFIG.bands[b].scene];
        if (img && img.width) {
          var sw = img.width, sh = sw * H / W;
          ctx.drawImage(img, 0, img.height * 0.18, sw, sh, 0, 0, W, H);
          ctx.fillStyle = "rgba(0,0,0,0.42)"; ctx.fillRect(0, 0, W, H);
        } else {
          var g = ctx.createLinearGradient(0, 0, 0, H);
          g.addColorStop(0, "#231a4a"); g.addColorStop(1, "#0b0820");
          ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
        }
        var rowsDrawn = 0;
        for (i = 0; i < list.length; i++) rowsDrawn = Math.max(rowsDrawn, +list[i].split("_")[0] + 1);
        rr = Math.min(14, (H - 12) / (2 + (rowsDrawn - 1) * SQ3));
        var x0 = (W - COLS * 2 * rr) / 2;
        var y0 = Math.max(8, (H - (rr * 2 + (rowsDrawn - 1) * rr * SQ3)) / 2);
        for (i = 0; i < list.length; i++) {
          var rc = list[i].split("_"), p = picCell(x0, y0, +rc[0], +rc[1], rr);
          picBubble(p.x, p.y, cells[list[i]], rr);
        }
      });
    }
    var BAND_PAGES = [
      { id: "marsh",  lv: 1,  show: 6, name: "Marsh", lines: [
        "Levels 1 and 2 start clean, with two colours. The rot breaks out after {n} s." ] },
      { id: "ruins",  lv: 7,  show: 10, name: "Ruins", lines: [
        "Almost every wall draws a shape: a diamond, a lattice, a ring, a cross." ] },
      { id: "gorge",  lv: 13, show: 16, name: "Gorge", lines: [
        "Most walls start with two outbreaks. You will have to hold two fronts at once." ] },
      { id: "castle", lv: 19, show: 22, name: "Castle", lines: [
        "New shapes to spot: an arrow, cherries, and more." ] },
      { id: "throne", lv: 25, show: 28, name: "Throne", lines: [
        "From level 26, every wall starts with three outbreaks." ] }
    ];
    function bandPage(i) {
      var B = BAND_PAGES[i], j;
      var lines = [];
      for (j = 0; j < B.lines.length; j++) lines.push(fill(Lang.t(B.lines[j]), { n: CONFIG.rotGrace }));
      return { id: B.id, title: Lang.t(B.name), lv: B.lv,
               pic: function () { return bandPic(i, B.show); },
               lines: lines };
    }

    var guide = {
      chapters: function () {
        // the stars are the level layer's default bands over the objective
        var goalRows = [["★ · ★★ · ★★★", "×1 · ×" + num(1.5) + " · ×" + num(2.2)]];
        return [
          { key: "basics", label: Lang.t("The basics"), pages: [
            { id: "goal", title: Lang.t("Race the rot"), pic: function () {
                return paintPic(460, 180, function () {
                  picWall(["ryxxby", "xbyxx", "bxxrry"], 50, 4);
                });
              }, rows: goalRows, lines: [
              Lang.t("There is no clock, only the rot. The round ends when the whole wall is rotten. If your score is still low, always keep some coloured bubbles — a total clear can sometimes be counterproductive.") ] },
            { id: "aim", title: Lang.t("Aim and shoot"), pic: function () {
                return paintPic(460, 260, function () {
                  var wall = picWall(["ybrrb", "byyb"], 40, 10);
                  picDots(picPath(150, 210, 1.15, wall, R, 460 - R));
                  picLauncher(150, 210);
                  picBubble(150, 210, 0);
                });
              }, lines: [
              Lang.t("Drag to aim, release to shoot.") ] },
            { id: "match", title: Lang.t("Match three"), pic: function () {
                return paintPic(460, 210, function () {
                  var wall = picWall(["byrrby", "yb.by"], 50, 6), p = picCell(50, 6, 1, 2);
                  picDots(picPath(p.x, 172, 0, wall, R, 460 - R));
                  picBubble(p.x, 172, 0, R, 1, -0.3, Math.PI / 2);
                });
              }, lines: [
              Lang.t("Every shot that pops raises your combo, up to ×6. A shot that pops nothing resets it.") ] },
            { id: "cascade", title: Lang.t("Falling bubbles"), pic: function () {
                return paintPic(460, 220, function () {
                  picWall(["yb..by", "b...y"], 50, 6);
                  var fall = [[160, 112, 0, 0.95], [292, 104, "x", 0.9], [222, 150, 1, 0.85], [300, 176, 2, 0.75]];
                  for (var f = 0; f < fall.length; f++)
                    picBubble(fall[f][0], fall[f][1], fall[f][2], R, fall[f][3], -0.25, Math.PI / 2);
                  // drawSplashes' own burst on the floor, lent one splash
                  var keepS = splashes;
                  splashes = [{ x: 170, y: 206, t: 0.12, life: 0.46, color: PAL[1].light, edge: PAL[1].core, power: 1.1 }];
                  try { drawSplashes(); } finally { splashes = keepS; }
                });
              }, rows: [[Lang.t("A bubble that falls"), "+" + CONFIG.fallBonus],
                        [Lang.t("A rotten bubble that falls"), "+" + CONFIG.fallBonus * 2]], lines: [
              Lang.t("Pop what holds a group to the ceiling, and the whole group falls.") ] },
            { id: "swap", title: Lang.t("Swap"), pic: function () {
                return paintPic(380, 150, function () {
                  var y = 92, sx = 130 + (SWAP_X - LX), nx = 130 + (NEXT_X - LX);
                  picLauncher(130, y);
                  picBubble(130, y, 2);
                  picSwapRing(sx, y);
                  picNext(nx, y, "s");
                });
              }, lines: [
              Lang.t("Tap the ring or the next bubble to swap the two."),
              Lang.t("Swapping costs no shot. Check the next bubble and fire it first if it fits better.") ] },
            { id: "press", title: Lang.t("The wall comes down"), pic: function () {
                return paintPic(460, 220, function () {
                  picWall(["byyrbr", "rbyyb", "yrrbby"], 50, 6);
                  picDanger(460, 204);
                });
              }, lines: [
              Lang.t("The wall moves down after a few shots. A bubble on the red line ends the round.") ] }
          ] },
          { key: "rot", label: Lang.t("The rot"), pages: [
            { id: "rot", title: Lang.t("The rot"), pic: function () {
                return paintPic(400, 130, function () {
                  picBubble(90, 65, 1);
                  picBubble(200, 65, { c: 1, t: 0.55, hole: Math.PI });
                  picBubble(310, 65, "x");
                });
              }, lines: [
              Lang.t("A rotten bubble never pops. Every few seconds, the rot reaches a bubble next to it."),
              Lang.t("A bubble filling with rot is still active. Pop it before it turns completely.") ] },
            { id: "outbreak", title: Lang.t("The rot spreads"), pic: function () {
                return paintPic(400, 200, function () {
                  picWall(["byrby", "ry.yb", "ybrb"], 60, 12);
                  var p = picCell(60, 12, 1, 2);
                  picBubble(p.x, p.y, { c: 0, t: 0.12, hole: -Math.PI / 2 });
                });
              }, lines: [
              Lang.t("Cutting the rot off won't stop it. It will break out somewhere else.") ] }
          ] },
          { key: "rainbow", label: Lang.t("The rainbow"), pages: [
            { id: "joker", title: Lang.t("Rainbow bubble"), pic: function () {
                return paintPic(460, 210, function () {
                  var wall = picWall(["rrsrry", "bys.b"], 50, 6), p = picCell(50, 6, 1, 3);
                  picDots(picPath(p.x, 172, 0, wall, R, 460 - R));
                  picBubble(p.x, 172, 0, R, 1, -0.3, Math.PI / 2);
                });
              }, lines: [
              Lang.t("A rainbow bubble in a cluster takes the right colour on impact."),
              Lang.t("A rainbow bubble can join two groups into one match. This Joker bubble never rots and can even decontaminate an area.") ] },
            { id: "cure", title: Lang.t("Rainbow shot"), pic: function () {
                return paintPic(460, 210, function () {
                  var wall = picWall(["xxbxxy", "rx.xb"], 50, 6), p = picCell(50, 6, 1, 2);
                  picDots(picPath(p.x, 172, 0, wall, R, 460 - R));
                  picBubble(p.x, 172, "s", R, 1, -0.3, Math.PI / 2);
                });
              }, rows: [[Lang.t("Bubbles saved"), CONFIG.cureMin + " → " + CONFIG.cureMax]], lines: [
              Lang.t("Fire a rainbow into the rot to give the bubbles their colour back."),
              Lang.t("The more rot there is, the more powerful the rainbow. Keep this bubble for the right moment.") ] }
          ] },
          { key: "climb", label: Lang.t("The climb"), pages: [
            bandPage(0), bandPage(1), bandPage(2), bandPage(3), bandPage(4)
          ] }
        ];
      }
    };

    function onTimeUp() { endRun(CONFIG.copy.timeUp); }

    function endRun(title) {
      if (ended) return;
      ended = true;
      chain = null;
      var best = Math.max(score, Store.get("bestScore", 0));
      var stars = score >= 3000 ? 3 : score >= 2000 ? 2 : score > 0 ? 1 : 0;
      endRound({
        title: title,
        variant: stars === 3 ? "win" : "",
        score: score,
        stars: stars,
        rows: [
          { label: "Bubbles cleared", value: totalCleared },
          { label: "Max chain",       value: maxCombo, grade: "accent" },
          { label: "Best score",      value: best,     grade: "gold" }
        ],
        track: { score: score, reason: title, maxCombo: maxCombo, cleared: totalCleared }
      });
    }

    /* --- THE LEVEL LAYER (web target) ------------------------------------
       The three-star finish: the web shell has already played the slow
       motion, and the round ends through the game's own result so the end
       screen keeps these stat rows. Ignored by the playable, which has no
       levels — see docs/LEVELS.md. */
    return { reset: reset, onDown: onDown, onMove: onMove, onUp: onUp,
             update: update, render: render, onTimeUp: onTimeUp, onResize: onResize,
             levelWon: endRun, guide: guide };
  })();
